    Object             : StoredProcedure SFin.SageInboundReceiptAndAllocation_Materialise
    Source schema hash : 4925D26F76C6D381C98BEE1B360E5392AE82B723F7131E6331F5326A90250F20
    Definition SHA-256 : CE80C7948B9AA5B764AB63A7EA1C95A46ED8CAC7693CF9472EE5D035D437D5BF

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SFin].[SageInboundReceiptAndAllocation_Materialise]
(
    @ExternalTransactionID BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @NowUtc DATETIME2(7) = GETUTCDATE(),
        @UserId INT,
        @SessionUserGuid UNIQUEIDENTIFIER,

        @MatchedInvoiceTransactionID BIGINT,
        @MatchedInvoiceTransactionGuid UNIQUEIDENTIFIER,

        @SageTransactionTypeCode INT,
        @AllocatedValue DECIMAL(18,2),
        @NetAmount DECIMAL(18,2),
        @TaxAmount DECIMAL(18,2),
        @TransactionDate DATE,
        @MatchedInvoiceDate DATE,
        @SageTransactionReference NVARCHAR(100),

        @InvoicePurchaseOrderNumber NVARCHAR(28),
        @InvoiceAccountGuid UNIQUEIDENTIFIER,
        @InvoiceJobGuid UNIQUEIDENTIFIER,
        @InvoiceOrganisationalUnitGuid UNIQUEIDENTIFIER,
        @InvoiceSurveyorGuid UNIQUEIDENTIFIER,
        @InvoiceCreditTermsGuid UNIQUEIDENTIFIER,
        @InvoiceDescription NVARCHAR(2000),

        @InvoiceActivityGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
        @InvoiceMilestoneGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
        @InvoiceJobPaymentStageGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
        @InvoiceRibaStageGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000',
        @InvoiceVatCodeGuid UNIQUEIDENTIFIER = NULL,        

        @MaterialisedTransactionTypeName NVARCHAR(50),
        @MaterialisedTransactionTypeGuid UNIQUEIDENTIFIER,
        @ReceiptGuid UNIQUEIDENTIFIER,
        @ReceiptDetailGuid UNIQUEIDENTIFIER,
        @AllocationGuid UNIQUEIDENTIFIER,

        @ReceiptTransactionId BIGINT,
        @AllocationId BIGINT,

        @ReceiptSageTransactionReference NVARCHAR(50),
        @ReceiptDescription NVARCHAR(2000),
        @VatRate DECIMAL(18,2),
        @NetToStore DECIMAL(18,2),
        @CreatedByUserGuid UNIQUEIDENTIFIER,
        @ExpectedDate DATE,

        @ExistingReceiptGuid UNIQUEIDENTIFIER,
        @ExistingAllocationGuid UNIQUEIDENTIFIER,
        @ExistingReceiptTransactionGuid UNIQUEIDENTIFIER,
        @ExistingAllocationMaterialisedGuid UNIQUEIDENTIFIER,

        @InvoiceHasDistinctAllocationSource BIT;

    SET @UserId = ISNULL(CONVERT(INT, SESSION_CONTEXT(N'user_id')), -1);
    SET @SessionUserGuid = SCore.GetCurrentUserGuid();

    BEGIN TRY
        SELECT
            @MatchedInvoiceTransactionID        = ext.MatchedTransactionID,
            @SageTransactionTypeCode             = ext.SageTransactionTypeCode,
            @AllocatedValue                     = ext.AllocatedValue,
            @NetAmount                          = ext.NetAmount,
            @TaxAmount                          = ext.TaxAmount,
            @TransactionDate                    = ext.TransactionDate,
            @SageTransactionReference           = ext.SageTransactionReference,
            @ExistingReceiptTransactionGuid     = ext.MaterialisedReceiptTransactionGuid,
            @ExistingAllocationMaterialisedGuid = ext.MaterialisedAllocationGuid
        FROM SFin.SageExternalTransactions AS ext
        WHERE ext.ID = @ExternalTransactionID
          AND ext.RowStatus NOT IN (0,254);

        /*
            Type 5 Credit Note and type 6 Receipt rows are the primary
            allocation sources created in CymBuild - Sage is the system of
            record for both and CymBuild only mirrors them inbound.

            Some Sage sources (including the DEV mock wrapper) never emit a
            distinct Credit Note/Receipt row at all: they represent a
            settled invoice purely by flipping IsPaid/AllocatedValue on the
            type 4 Invoice row itself. Without a fallback, CYB-543 invoices
            reach PaymentStateCode = Paid but never get a materialised
            Receipt/Allocation. So a type 4 row is also accepted as an
            allocation source, but only while no distinct type 5/6 row has
            ever been matched to the same invoice - once a real Credit
            Note/Receipt exists, it alone owns the receipt/allocation so the
            two sources cannot fight over (and repeatedly overwrite) the
            same materialised amount.
        */
        SET @InvoiceHasDistinctAllocationSource = 0;

        IF @SageTransactionTypeCode = 4
           AND ISNULL(@MatchedInvoiceTransactionID, -1) > 0
           AND EXISTS
           (
                SELECT 1
                FROM SFin.SageExternalTransactions AS distinctSource
                WHERE distinctSource.RowStatus NOT IN (0,254)
                  AND distinctSource.SageTransactionTypeCode IN (5, 6)
                  AND distinctSource.MatchedTransactionID = @MatchedInvoiceTransactionID
           )
        BEGIN
            SET @InvoiceHasDistinctAllocationSource = 1;
        END;

        SET @MaterialisedTransactionTypeName =
            CASE @SageTransactionTypeCode
                WHEN 5 THEN N'CreditNote'
                WHEN 6 THEN N'Receipt'
                WHEN 4 THEN CASE WHEN @InvoiceHasDistinctAllocationSource = 0 THEN N'Receipt' ELSE NULL END
                ELSE NULL
            END;

        IF @MaterialisedTransactionTypeName IS NULL
        BEGIN
            RETURN;
        END;

        -- Sage can return negative accounting values for Credit Notes. CymBuild
        -- stores positive detail/allocation values and applies the sign through
        -- TransactionTypes.IsNegated.
        SET @AllocatedValue = ABS(ISNULL(@AllocatedValue, 0));
        SET @NetAmount = ABS(ISNULL(@NetAmount, 0));
        SET @TaxAmount = ABS(ISNULL(@TaxAmount, 0));

        IF ISNULL(@MatchedInvoiceTransactionID, -1) <= 0
        BEGIN
            RETURN;
        END;

        IF ISNULL(@AllocatedValue, 0) <= 0
        BEGIN
            RETURN;
        END;

        /*
            A type 4 fallback materialisation (see above) and a genuine type
            5/6 row can each reach this point for the same invoice, in
            either order, across separate poll cycles. Reuse whichever
            Receipt/Allocation is already materialised for this invoice -
            from this row or a sibling row - so the later of the two
            updates the existing pair in place instead of creating a
            duplicate.
        */
        IF ISNULL(@ExistingReceiptTransactionGuid, '00000000-0000-0000-0000-000000000000') = '00000000-0000-0000-0000-000000000000'
        BEGIN
            SELECT TOP (1)
                @ExistingReceiptTransactionGuid     = siblingExt.MaterialisedReceiptTransactionGuid,
                @ExistingAllocationMaterialisedGuid = siblingExt.MaterialisedAllocationGuid
            FROM SFin.SageExternalTransactions AS siblingExt
            WHERE siblingExt.RowStatus NOT IN (0,254)
              AND siblingExt.ID <> @ExternalTransactionID
              AND siblingExt.MatchedTransactionID = @MatchedInvoiceTransactionID
              AND siblingExt.MaterialisedReceiptTransactionGuid IS NOT NULL
              AND siblingExt.MaterialisedReceiptTransactionGuid <> '00000000-0000-0000-0000-000000000000'
            ORDER BY siblingExt.ID DESC;
        END;

        SELECT
            @MatchedInvoiceTransactionGuid = t.Guid,
            @InvoicePurchaseOrderNumber    = t.PurchaseOrderNumber,
            @MatchedInvoiceDate            = t.[Date]
        FROM SFin.Transactions AS t
        WHERE t.ID = @MatchedInvoiceTransactionID
          AND t.RowStatus NOT IN (0,254);

        IF @MatchedInvoiceTransactionGuid IS NULL
        BEGIN
            RETURN;
        END;

        SELECT TOP (1)
            @InvoiceDescription         = td.Description,
            @InvoiceActivityGuid        = ISNULL(act.Guid, '00000000-0000-0000-0000-000000000000'),
            @InvoiceMilestoneGuid       = ISNULL(ms.Guid, '00000000-0000-0000-0000-000000000000'),
            @InvoiceJobPaymentStageGuid = ISNULL(jps.Guid, '00000000-0000-0000-0000-000000000000'),
            @InvoiceRibaStageGuid       = ISNULL(rs.Guid, '00000000-0000-0000-0000-000000000000'),
            @InvoiceVatCodeGuid         = vc.Guid
        FROM SFin.TransactionDetails AS td
        LEFT JOIN SJob.Activities AS act
            ON act.ID = td.ActivityID
        LEFT JOIN SJob.Milestones AS ms
            ON ms.ID = td.MilestoneID
        LEFT JOIN SJob.JobPaymentStages AS jps
            ON jps.ID = td.JobPaymentStageId
        LEFT JOIN SJob.RibaStages AS rs
            ON rs.ID = td.RIBAStageId
        LEFT JOIN SFin.VatCodes AS vc
            ON vc.ID = td.VatCodeID
           AND vc.RowStatus NOT IN (0,254)
           AND vc.Active = 1
        WHERE td.TransactionID = @MatchedInvoiceTransactionID
          AND td.RowStatus NOT IN (0,254)
        ORDER BY td.ID;

        SELECT
            @InvoiceAccountGuid            = acc.Guid,
            @InvoiceJobGuid                = j.Guid,
            @InvoiceOrganisationalUnitGuid = ou.Guid,
            @InvoiceSurveyorGuid           = idn.Guid,
            @InvoiceCreditTermsGuid        = ct.Guid
        FROM SFin.Transactions AS t
        JOIN SCrm.Accounts AS acc
            ON acc.ID = t.AccountID
        JOIN SJob.Jobs AS j
            ON j.ID = t.JobID
        JOIN SCore.OrganisationalUnits AS ou
            ON ou.ID = t.OrganisationalUnitId
        JOIN SCore.Identities AS idn
            ON idn.ID = t.SurveyorUserId
        JOIN SFin.CreditTerms AS ct
            ON ct.ID = t.CreditTermsId
        WHERE t.ID = @MatchedInvoiceTransactionID
          AND t.RowStatus NOT IN (0,254);

        -- Sage's transaction date remains authoritative when supplied. Some
        -- legacy/wrapper rows do not contain transactionDate; in that case the
        -- matched CymBuild invoice date is the deterministic fallback.
        SET @TransactionDate = COALESCE(@TransactionDate, @MatchedInvoiceDate);

        IF @TransactionDate IS NULL
        BEGIN
            ;THROW 60081, N'Allocation-source date could not be resolved from the Sage external transaction or matched CymBuild invoice.', 1;
        END;

        SET @CreatedByUserGuid = ISNULL(@InvoiceSurveyorGuid, @SessionUserGuid);
        SET @ExpectedDate = @TransactionDate;

        SELECT TOP (1)
            @MaterialisedTransactionTypeGuid = tt.Guid
        FROM SFin.TransactionTypes AS tt
        WHERE tt.RowStatus NOT IN (0,254)
          AND tt.IsActive = 1
          AND UPPER(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(tt.Name)), N' ', N''), N'-', N''), N'_', N'')) =
              UPPER(REPLACE(REPLACE(REPLACE(@MaterialisedTransactionTypeName, N' ', N''), N'-', N''), N'_', N''))
        ORDER BY tt.ID;

        IF @MaterialisedTransactionTypeGuid IS NULL
        BEGIN
            ;THROW 60000, N'Could not resolve the finance TransactionType required by the Sage allocation source.', 1;
        END;

        SET @ReceiptSageTransactionReference =
            ISNULL(@SageTransactionReference, N'');

        SET @ReceiptDescription =
            LEFT(ISNULL(@SageTransactionReference, N'')
                + CASE
                    WHEN ISNULL(@InvoiceDescription, N'') = N'' THEN N''
                    ELSE CHAR(13) + CHAR(10) + @InvoiceDescription
                  END,
                2000
            );

        SET @NetToStore =
            CASE
                WHEN ISNULL(@NetAmount, 0) > 0 THEN @NetAmount
                ELSE ISNULL(@AllocatedValue, 0) - ISNULL(@TaxAmount, 0)
            END;

        SET @VatRate =
            CASE
                WHEN ISNULL(@NetToStore, 0) > 0
                 AND ISNULL(@TaxAmount, 0) > 0
                    THEN ROUND((@TaxAmount / NULLIF(@NetToStore, 0)) * 100.0, 2)
                ELSE 0
            END;

        SET @ReceiptGuid = NULLIF(
            @ExistingReceiptTransactionGuid,
            '00000000-0000-0000-0000-000000000000');

        IF @ReceiptGuid IS NULL
        BEGIN
            SELECT TOP (1)
                @ExistingReceiptGuid = t.Guid
            FROM SFin.Transactions AS t
            JOIN SFin.TransactionTypes AS tt
                ON tt.ID = t.TransactionTypeID
               AND tt.RowStatus NOT IN (0,254)
            WHERE t.RowStatus NOT IN (0,254)
              AND UPPER(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(tt.Name)), N' ', N''), N'-', N''), N'_', N'')) =
                  UPPER(REPLACE(REPLACE(REPLACE(@MaterialisedTransactionTypeName, N' ', N''), N'-', N''), N'_', N''))
              AND t.Date = @TransactionDate
              AND t.SageTransactionReference = @ReceiptSageTransactionReference
              AND t.AccountID = (
                    SELECT TOP (1) a.ID
                    FROM SCrm.Accounts AS a
                    WHERE a.Guid = @InvoiceAccountGuid
                      AND a.RowStatus NOT IN (0,254)
              )
              AND t.JobID = (
                    SELECT TOP (1) j2.ID
                    FROM SJob.Jobs AS j2
                    WHERE j2.Guid = @InvoiceJobGuid
                      AND j2.RowStatus NOT IN (0,254)
              )
            ORDER BY t.ID DESC;

            SET @ReceiptGuid = @ExistingReceiptGuid;
        END;

        IF @ReceiptGuid IS NULL
           OR @ReceiptGuid = '00000000-0000-0000-0000-000000000000'
        BEGIN
            SET @ReceiptGuid = NEWID();
        END;

        EXECUTE SFin.TransactionsUpsert
             @AccountGuid = @InvoiceAccountGuid,
             @JobGuid = @InvoiceJobGuid,
             @TransactionTypeGuid = @MaterialisedTransactionTypeGuid,
             @Date = @TransactionDate,
             @PurchaseOrderNumber = @InvoicePurchaseOrderNumber,
             @SageTransactionReference = @ReceiptSageTransactionReference,
             @OrganisationalUnitGuid = @InvoiceOrganisationalUnitGuid,
             @CreatedByUserGuid = @CreatedByUserGuid,
             @SurveyorGuid = @InvoiceSurveyorGuid,
             @CreditTermsGuid = @InvoiceCreditTermsGuid,
             @Guid = @ReceiptGuid,
             @Batched = 0,
             @ExpectedDate = @ExpectedDate;

        SELECT TOP (1)
            @ReceiptTransactionId = t.ID
        FROM SFin.Transactions AS t
        WHERE t.Guid = @ReceiptGuid
          AND t.RowStatus NOT IN (0,254)
        ORDER BY t.ID DESC;

        IF ISNULL(@ReceiptTransactionId, -1) <= 0
        BEGIN
            ;THROW 60000, N'Sage allocation-source transaction could not be resolved after upsert.', 1;
        END;

        -- SFin.TransactionsUpsert always inserts a brand-new transaction with
        -- Batched = 1 (it ignores @Batched on insert - new manually-raised
        -- transactions must start in the approval batch). A Sage-materialised
        -- receipt is already confirmed by Sage, so it must never sit there
        -- waiting for manual approval; correct it directly here rather than
        -- relying on a later poll to update it through TransactionsUpsert's
        -- update path.
        UPDATE SFin.Transactions
        SET Batched = 0
        WHERE ID = @ReceiptTransactionId
          AND RowStatus NOT IN (0,254)
          AND Batched = 1;

        SELECT TOP (1)
            @ReceiptDetailGuid = td.Guid
        FROM SFin.TransactionDetails AS td
        WHERE td.TransactionID = @ReceiptTransactionId
          AND td.RowStatus NOT IN (0,254)
        ORDER BY td.ID DESC;

        IF @ReceiptDetailGuid IS NULL OR @ReceiptDetailGuid = '00000000-0000-0000-0000-000000000000'
        BEGIN
            SET @ReceiptDetailGuid = NEWID();
        END;

        IF @InvoiceVatCodeGuid IS NULL
           OR @InvoiceVatCodeGuid = '00000000-0000-0000-0000-000000000000'
        BEGIN
            ;THROW 60080, N'Invoice VAT code could not be resolved for Sage allocation-source materialisation.', 1;
        END;

        EXECUTE SFin.TransactionDetailsUpsert
             @TransactionGuid = @ReceiptGuid,
             @MilestoneGuid = @InvoiceMilestoneGuid,
             @ActivityGuid = @InvoiceActivityGuid,
             @Net = @NetToStore,
             @Vat = 0,
             @Gross = 0,
             @VatRate = @VatRate,
             @Description = @ReceiptDescription,
             @JobPaymentStageGuid = @InvoiceJobPaymentStageGuid,
             @Guid = @ReceiptDetailGuid,
             @RIBAStageGuid = @InvoiceRibaStageGuid,
             @InvoiceRequestItemGuid = NULL,
             @Qty = 1,
             @VatCodeGuid = @InvoiceVatCodeGuid;

        SET @AllocationGuid = NULLIF(
            @ExistingAllocationMaterialisedGuid,
            '00000000-0000-0000-0000-000000000000');

        IF @AllocationGuid IS NULL
        BEGIN
            SELECT TOP (1)
                @ExistingAllocationGuid = ta.Guid
            FROM SFin.TransactionAllocations AS ta
            WHERE ta.RowStatus NOT IN (0,254)
              AND ta.SourceTransactionID = @ReceiptTransactionId
              AND ta.TargetTransactionID = @MatchedInvoiceTransactionID
            ORDER BY ta.ID DESC;

            SET @AllocationGuid = @ExistingAllocationGuid;
        END;

        IF @AllocationGuid IS NULL
           OR @AllocationGuid = '00000000-0000-0000-0000-000000000000'
        BEGIN
            SET @AllocationGuid = NEWID();
        END;

        -- Reusing the allocation Guid makes later increases in Sage's cumulative
        -- allocated value an update, rather than a duplicate allocation.
        EXECUTE SFin.TransactionAllocationsUpsert
             @SourceTransactionGuid = @ReceiptGuid,
             @TargetTransactionGuid = @MatchedInvoiceTransactionGuid,
             @AllocatedValue = @AllocatedValue,
             @Guid = @AllocationGuid;

        SELECT TOP (1)
            @AllocationId = ta.ID
        FROM SFin.TransactionAllocations AS ta
        WHERE ta.Guid = @AllocationGuid
          AND ta.RowStatus NOT IN (0,254)
        ORDER BY ta.ID DESC;

        UPDATE ext
        SET
            MaterialisedReceiptTransactionID   = @ReceiptTransactionId,
            MaterialisedReceiptTransactionGuid = @ReceiptGuid,
            MaterialisedAllocationID           = @AllocationId,
            MaterialisedAllocationGuid         = @AllocationGuid,
            ReceiptMaterialisedOnUtc           = @NowUtc,
            ReceiptMaterialisationError        = N'',
            UpdatedByUserID                    = @UserId,
            UpdatedDateTimeUTC                 = @NowUtc
        FROM SFin.SageExternalTransactions AS ext
        WHERE ext.ID = @ExternalTransactionID
          AND ext.RowStatus NOT IN (0,254);

    END TRY
    BEGIN CATCH
        UPDATE ext
        SET
            ReceiptMaterialisationError = LEFT(ERROR_MESSAGE(), 2000),
            UpdatedByUserID             = @UserId,
            UpdatedDateTimeUTC          = GETUTCDATE()
        FROM SFin.SageExternalTransactions AS ext
        WHERE ext.ID = @ExternalTransactionID
          AND ext.RowStatus NOT IN (0,254);

        THROW;
    END CATCH;
END;
GO

GO

/* Deploy StoredProcedure SFin.SageInboundReceiptMaterialisation_AutoCorrect using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SFin.SageInboundReceiptMaterialisation_AutoCorrect.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SFin.SageInboundReceiptMaterialisation_AutoCorrect
    Source schema hash : CEA974D1ED4C84A656DCFB76153E3DDC0F7CEF54EB4F2A5B3847ED274D84256C
    Definition SHA-256 : E407B2DF0B6FF617CB4B0CABD4BB2DFED17C5D5601512B8221F151E67C0F4B99

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SFin].[SageInboundReceiptMaterialisation_AutoCorrect]
(
    @ExternalTransactionID BIGINT = NULL,
    @BatchSize INT = 100,
    @DryRun BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT OFF;

    DECLARE
        @CurrentExternalTransactionID BIGINT,
        @ProcessedCount INT = 0,
        @CorrectedCount INT = 0,
        @SkippedCount INT = 0,
        @FailedCount INT = 0;

    DECLARE @Candidates TABLE
    (
        RowNumber INT IDENTITY(1,1) NOT NULL,
        ExternalTransactionID BIGINT NOT NULL
    );

    DECLARE @Results TABLE
    (
        ExternalTransactionID BIGINT NOT NULL,
        Outcome NVARCHAR(30) NOT NULL,
        Message NVARCHAR(2000) NOT NULL,
        MatchedTransactionID BIGINT NULL,
        MaterialisedReceiptTransactionID BIGINT NULL,
        MaterialisedAllocationID BIGINT NULL
    );

    INSERT INTO @Candidates
    (
        ExternalTransactionID
    )
    SELECT TOP (@BatchSize)
        ext.ID
    FROM SFin.SageExternalTransactions AS ext
    WHERE ext.RowStatus NOT IN (0,254)
      -- CYB-543: an Invoice (4) row is also a fixable candidate when Sage never sent a
      -- distinct Credit Note/Receipt row for it - see SFin.SageInboundReceiptAndAllocation_Materialise.
      AND (ext.SageTransactionTypeCode IN (5, 6) OR ext.SageTransactionTypeCode = 4)
      AND ABS(ISNULL(ext.AllocatedValue, 0)) > 0
      AND
      (
            @ExternalTransactionID IS NULL
         OR ext.ID = @ExternalTransactionID
      )
      AND ext.MaterialisedReceiptTransactionID IS NULL
    ORDER BY ext.ID;

    IF @DryRun = 1
    BEGIN
        SELECT
            ProcessedCount = COUNT(1),
            CorrectedCount = 0,
            SkippedCount = COUNT(1),
            FailedCount = 0
        FROM @Candidates;

        SELECT
            c.ExternalTransactionID,
            Outcome = N'DryRun',
            Message = N'Candidate would be reconciled and materialised.',
            MatchedTransactionID = ext.MatchedTransactionID,
            MaterialisedReceiptTransactionID = ext.MaterialisedReceiptTransactionID,
            MaterialisedAllocationID = ext.MaterialisedAllocationID
        FROM @Candidates AS c
        JOIN SFin.SageExternalTransactions AS ext
            ON ext.ID = c.ExternalTransactionID
           AND ext.RowStatus NOT IN (0,254)
        ORDER BY c.ExternalTransactionID;

        RETURN;
    END;

    DECLARE candidate_cursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT
        c.ExternalTransactionID
    FROM @Candidates AS c
    ORDER BY c.ExternalTransactionID;

    OPEN candidate_cursor;

    FETCH NEXT FROM candidate_cursor INTO @CurrentExternalTransactionID;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        BEGIN TRY
            DECLARE @ReconcileResult TABLE
            (
                ExternalTransactionID BIGINT,
                IsMatched BIT,
                MatchedTransactionID BIGINT,
                MatchedTransactionGuid UNIQUEIDENTIFIER,
                MatchedInvoiceRequestID INT,
                MatchedJobID INT,
                MatchRule NVARCHAR(100)
            );

            DECLARE @PaymentStateResult TABLE
            (
                ExternalTransactionID BIGINT,
                PaymentStateCode NVARCHAR(30),
                AllocatedValue DECIMAL(18,2),
                OutstandingAmount DECIMAL(18,2),
                GrossAmount DECIMAL(18,2),
                DocumentDiscountedValue DECIMAL(18,2),
                IsPaid BIT,
                IsFullyPaid BIT
            );

            INSERT INTO @ReconcileResult
            (
                ExternalTransactionID,
                IsMatched,
                MatchedTransactionID,
                MatchedTransactionGuid,
                MatchedInvoiceRequestID,
                MatchedJobID,
                MatchRule
            )
            EXEC SFin.SageInbound_ReconcileInvoiceTransaction
                @ExternalTransactionID = @CurrentExternalTransactionID;

            INSERT INTO @PaymentStateResult
            (
                ExternalTransactionID,
                PaymentStateCode,
                AllocatedValue,
                OutstandingAmount,
                GrossAmount,
                DocumentDiscountedValue,
                IsPaid,
                IsFullyPaid
            )
            EXEC SFin.SageInbound_ApplyAggregatePaymentState
                @ExternalTransactionID = @CurrentExternalTransactionID;

            EXEC SFin.SageInboundReceiptAndAllocation_Materialise
                @ExternalTransactionID = @CurrentExternalTransactionID;

            INSERT INTO @Results
            (
                ExternalTransactionID,
                Outcome,
                Message,
                MatchedTransactionID,
                MaterialisedReceiptTransactionID,
                MaterialisedAllocationID
            )
            SELECT
                ext.ID,
                CASE
                    WHEN ext.MaterialisedReceiptTransactionID IS NOT NULL
                     AND ext.MaterialisedAllocationID IS NOT NULL
                        THEN N'Corrected'
                    WHEN ISNULL(ext.MatchedTransactionID, -1) <= 0
                        THEN N'Skipped'
                    ELSE N'Skipped'
                END,
                CASE
                    WHEN ext.MaterialisedReceiptTransactionID IS NOT NULL
                     AND ext.MaterialisedAllocationID IS NOT NULL
                        THEN N'Sage Credit Note/Receipt and allocation materialised.'
                    WHEN ISNULL(ext.MatchedTransactionID, -1) <= 0
                        THEN N'Could not reconcile external transaction to a CymBuild invoice transaction.'
                    ELSE N'Materialisation did not create an allocation-source transaction. Check ReceiptMaterialisationError.'
                END,
                ext.MatchedTransactionID,
                ext.MaterialisedReceiptTransactionID,
                ext.MaterialisedAllocationID
            FROM SFin.SageExternalTransactions AS ext
            WHERE ext.ID = @CurrentExternalTransactionID
              AND ext.RowStatus NOT IN (0,254);
        END TRY
        BEGIN CATCH
            SET @FailedCount += 1;

            UPDATE ext
            SET
                ReceiptMaterialisationError = LEFT(ERROR_MESSAGE(), 2000),
                UpdatedByUserID = SCore.GetCurrentUserId(),
                UpdatedDateTimeUTC = GETUTCDATE()
            FROM SFin.SageExternalTransactions AS ext
            WHERE ext.ID = @CurrentExternalTransactionID
              AND ext.RowStatus NOT IN (0,254);

            INSERT INTO @Results
            (
                ExternalTransactionID,
                Outcome,
                Message,
                MatchedTransactionID,
                MaterialisedReceiptTransactionID,
                MaterialisedAllocationID
            )
            SELECT
                ext.ID,
                N'Failed',
                LEFT(ERROR_MESSAGE(), 2000),
                ext.MatchedTransactionID,
                ext.MaterialisedReceiptTransactionID,
                ext.MaterialisedAllocationID
            FROM SFin.SageExternalTransactions AS ext
            WHERE ext.ID = @CurrentExternalTransactionID
              AND ext.RowStatus NOT IN (0,254);
        END CATCH;

        FETCH NEXT FROM candidate_cursor INTO @CurrentExternalTransactionID;
    END;

    CLOSE candidate_cursor;
    DEALLOCATE candidate_cursor;

    SELECT
        @ProcessedCount = COUNT(1),
        @CorrectedCount = SUM(CASE WHEN Outcome = N'Corrected' THEN 1 ELSE 0 END),
        @SkippedCount = SUM(CASE WHEN Outcome = N'Skipped' THEN 1 ELSE 0 END),
        @FailedCount = SUM(CASE WHEN Outcome = N'Failed' THEN 1 ELSE 0 END)
    FROM @Results;

    SELECT
        ProcessedCount = ISNULL(@ProcessedCount, 0),
        CorrectedCount = ISNULL(@CorrectedCount, 0),
        SkippedCount = ISNULL(@SkippedCount, 0),
        FailedCount = ISNULL(@FailedCount, 0);

    SELECT
        ExternalTransactionID,
        Outcome,
        Message,
        MatchedTransactionID,
        MaterialisedReceiptTransactionID,
        MaterialisedAllocationID
    FROM @Results
    ORDER BY ExternalTransactionID;
END;
GO

GO

/* Deploy StoredProcedure SFin.TransactionDetailsUpsert using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SFin.TransactionDetailsUpsert.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SFin.TransactionDetailsUpsert
    Source schema hash : 6D88E82B53CE7BE5E03CDA609C5EEAE8FBB3E5E794841EAC333B65F8546E4A8B
    Definition SHA-256 : 9B8EC7305EBFD4E8DAACD92F6A0D16E9E00CAFA653E9693F2428CFA0D262A34F

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SFin].[TransactionDetailsUpsert]
(
      @TransactionGuid          UNIQUEIDENTIFIER
    , @MilestoneGuid            UNIQUEIDENTIFIER
    , @ActivityGuid             UNIQUEIDENTIFIER
    , @Net                      DECIMAL(9, 2)
    , @Vat                      DECIMAL(9, 2)
    , @Gross                    DECIMAL(9, 2)
    , @VatRate                  DECIMAL(9, 2)
    , @Description              NVARCHAR(2000)
    , @JobPaymentStageGuid      UNIQUEIDENTIFIER
    , @Guid                     UNIQUEIDENTIFIER
    , @RIBAStageGuid            UNIQUEIDENTIFIER
    , @InvoiceRequestItemGuid   UNIQUEIDENTIFIER = NULL
    , @Qty                      DECIMAL(18, 4) = 1
    , @VatCodeGuid              UNIQUEIDENTIFIER = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
          @TransactionID              BIGINT
        , @MilestoneID                BIGINT = -1
        , @ActivityID                 BIGINT = -1
        , @JobPaymentStageID          INT    = -1
        , @RIBAStageID                INT    = -1
        , @InvoiceRequestItemID       BIGINT = -1
        , @VatCodeID                  INT
        , @ResolvedVatRate            DECIMAL(9, 4)
        , @IsInsert                   BIT
        , @TransactionTypeName        NVARCHAR(50)
        , @TransactionTypeIsNegated   BIT = 0
        , @TransactionTypeIsBank      BIT = 0
        , @JobNumber                  NVARCHAR(2000)
        , @JobDescription             NVARCHAR(2000)
        , @JobType                    NVARCHAR(2000)
        , @UprnFormattedAddressComma  NVARCHAR(2000);

    IF @Guid IS NULL OR @Guid = '00000000-0000-0000-0000-000000000000'
    BEGIN
        ;THROW 60070, N'A valid Guid is required for SFin.TransactionDetailsUpsert.', 1;
    END;

    IF @TransactionGuid IS NULL OR @TransactionGuid = '00000000-0000-0000-0000-000000000000'
    BEGIN
        ;THROW 60071, N'A valid TransactionGuid is required for SFin.TransactionDetailsUpsert.', 1;
    END;

    IF @VatCodeGuid IS NULL OR @VatCodeGuid = '00000000-0000-0000-0000-000000000000'
    BEGIN
        ;THROW 60072, N'A valid VatCodeGuid is required for SFin.TransactionDetailsUpsert.', 1;
    END;

    IF @Qty IS NULL OR @Qty <= 0
    BEGIN
        SET @Qty = 1;
    END;

    SELECT
          @TransactionID = t.ID
        , @TransactionTypeName = tt.Name
        , @TransactionTypeIsNegated = ISNULL(tt.IsNegated, 0)
        , @TransactionTypeIsBank = ISNULL(tt.IsBank, 0)
    FROM SFin.Transactions AS t
    INNER JOIN SFin.TransactionTypes AS tt
        ON tt.ID = t.TransactionTypeID
       AND tt.RowStatus NOT IN (0, 254)
    WHERE t.Guid = @TransactionGuid
      AND t.RowStatus NOT IN (0, 254);

    IF @TransactionID IS NULL
    BEGIN
        ;THROW 60073, N'Transaction could not be resolved for SFin.TransactionDetailsUpsert.', 1;
    END;

    IF @MilestoneGuid IS NOT NULL
       AND @MilestoneGuid <> '00000000-0000-0000-0000-000000000000'
    BEGIN
        SELECT
            @MilestoneID = m.ID
        FROM SJob.Milestones AS m
        WHERE m.Guid = @MilestoneGuid
          AND m.RowStatus NOT IN (0, 254);
    END;

    IF @ActivityGuid IS NOT NULL
       AND @ActivityGuid <> '00000000-0000-0000-0000-000000000000'
    BEGIN
        SELECT
            @ActivityID = a.ID
        FROM SJob.Activities AS a
        WHERE a.Guid = @ActivityGuid
          AND a.RowStatus NOT IN (0, 254);
    END;

    IF @RIBAStageGuid IS NOT NULL
       AND @RIBAStageGuid <> '00000000-0000-0000-0000-000000000000'
    BEGIN
        SELECT
            @RIBAStageID = rs.ID
        FROM SJob.RibaStages AS rs
        WHERE rs.Guid = @RIBAStageGuid
          AND rs.RowStatus NOT IN (0, 254);
    END;

    IF @JobPaymentStageGuid IS NOT NULL
       AND @JobPaymentStageGuid <> '00000000-0000-0000-0000-000000000000'
    BEGIN
        SELECT
            @JobPaymentStageID = jps.ID
        FROM SJob.JobPaymentStages AS jps
        WHERE jps.Guid = @JobPaymentStageGuid
          AND jps.RowStatus NOT IN (0, 254);
    END;

    IF @InvoiceRequestItemGuid IS NOT NULL
       AND @InvoiceRequestItemGuid <> '00000000-0000-0000-0000-000000000000'
    BEGIN
        SELECT
            @InvoiceRequestItemID = iri.ID
        FROM SFin.InvoiceRequestItems AS iri
        WHERE iri.Guid = @InvoiceRequestItemGuid
          AND iri.RowStatus NOT IN (0, 254);
    END;

    SELECT
          @VatCodeID = vc.ID
        , @ResolvedVatRate = vc.VatPercentage
    FROM SFin.VatCodes AS vc
    WHERE vc.Guid = @VatCodeGuid
      AND vc.RowStatus NOT IN (0, 254)
      AND vc.Active = 1;

    IF @VatCodeID IS NULL
    BEGIN
        ;THROW 60074, N'VatCode could not be resolved for SFin.TransactionDetailsUpsert.', 1;
    END;

    IF @ResolvedVatRate IS NULL
    BEGIN
        ;THROW 60075, N'VatCode selected does not contain a valid VAT percentage for SFin.TransactionDetailsUpsert.', 1;
    END;

    /*
        VAT rate is now owned by the selected VatCode.
        Ignore caller-supplied @VatRate / @Vat / @Gross and recalculate deterministically.
    */
    SET @VatRate = CONVERT(DECIMAL(9, 2), @ResolvedVatRate);
    SET @Vat = ROUND(@Net * (@ResolvedVatRate / 100.0), 2);
    SET @Gross = ROUND(@Net + @Vat, 2);

    /*
        Fee-cap validation must only apply to finance transactions that consume
        job fee drawdown. Inbound Sage receipt materialisation also uses this
        upsert to create bank-side receipt details, but receipts must not be
        blocked by invoice fee-cap remaining values.

        TransactionTypes.IsBank keeps the logic data-driven and preserves the
        existing accounting sign convention, where TransactionCalculations uses
        IsNegated rather than storing negative line values directly.

        The explicit Receipt/Payment exclusion protects the inbound path even
        if historic reference data has not marked a bank-side transaction type
        as IsBank = 1 yet.
    */
    IF ISNULL(@TransactionTypeIsBank, 0) = 0
       AND ISNULL(@TransactionTypeIsNegated, 0) = 0
       AND ISNULL(@TransactionTypeName, N'') NOT IN (N'Receipt', N'Payment')
       AND ISNULL(@Net, 0) > 0
    BEGIN
        DECLARE @JobGuid UNIQUEIDENTIFIER;
        DECLARE @RemainingAmount DECIMAL(19,2);
        DECLARE @ExistingDetailNetForGuard DECIMAL(19,2) = 0;
        DECLARE @FeeCapGuardAvailableAmount DECIMAL(19,2);

        SELECT
            @JobGuid = j.Guid
        FROM SFin.Transactions AS root_hobt
        LEFT JOIN SJob.Jobs AS j
            ON root_hobt.JobID = j.ID
           AND j.RowStatus NOT IN (0, 254)
        WHERE root_hobt.ID = @TransactionID
          AND root_hobt.RowStatus NOT IN (0, 254);

        SELECT
            @RemainingAmount = fd.Remaining
        FROM SJob.Job_FeeDrawdown AS fd
        INNER JOIN SJob.Jobs AS j
            ON j.ID = fd.JobId
           AND j.RowStatus NOT IN (0, 254)
        WHERE j.Guid = @JobGuid
          AND fd.StageLabel = N'Total (inc. Fee Cap)';

        SELECT
            @ExistingDetailNetForGuard = ISNULL(SUM(ISNULL(td.Net, 0)), 0)
        FROM SFin.TransactionDetails AS td
        WHERE td.Guid = @Guid
          AND td.TransactionID = @TransactionID
          AND td.RowStatus NOT IN (0, 254);

        SET @FeeCapGuardAvailableAmount = @RemainingAmount + ISNULL(@ExistingDetailNetForGuard, 0);

        IF @RemainingAmount IS NOT NULL
           AND @Net > @FeeCapGuardAvailableAmount
        BEGIN
            DECLARE @ErrorMessageDirect NVARCHAR(500);

            SET @ErrorMessageDirect =
                      N'Cannot save this transaction because only the total of £'
                    + CONVERT(NVARCHAR(50), @FeeCapGuardAvailableAmount)
                    + N' remains'
                    + N', but the transaction Net is £'
                    + CONVERT(NVARCHAR(50), @Net)
                    + N'.';

            THROW 51003, @ErrorMessageDirect, 1;
        END;
    END;

    EXEC SCore.UpsertDataObject
          @Guid       = @Guid
        , @SchemeName = N'SFin'
        , @ObjectName = N'TransactionDetails'
        , @IsInsert   = @IsInsert OUTPUT;

    IF @IsInsert = 1
    BEGIN
        SELECT
              @JobNumber = j.Number
            , @JobDescription = j.JobDescription
            , @JobType = jt.Name
            , @UprnFormattedAddressComma = p.FormattedAddressComma
        FROM SJob.Jobs AS j
        INNER JOIN SJob.JobTypes AS jt
            ON jt.ID = j.JobTypeID
        INNER JOIN SJob.Assets AS p
            ON p.ID = j.UprnID
        INNER JOIN SFin.Transactions AS t
            ON t.JobID = j.ID
        WHERE t.Guid = @TransactionGuid
          AND j.RowStatus NOT IN (0, 254)
          AND jt.RowStatus NOT IN (0, 254)
          AND p.RowStatus NOT IN (0, 254)
          AND t.RowStatus NOT IN (0, 254);

        IF @@ROWCOUNT > 0
        BEGIN
            SET @Description =
                ISNULL(@Description, N'')
                + N'
Our project ref.: ' + ISNULL(@JobNumber, N'')
                + N'
Project description: ' + ISNULL(@JobDescription, N'')
                + N'
Property: ' + ISNULL(@UprnFormattedAddressComma, N'')
                + N'
Appointed role: ' + ISNULL(@JobType, N'');
        END;

        SET @Description = REPLACE(@Description, CHAR(34), CHAR(39));

        INSERT INTO SFin.TransactionDetails
        (
              RowStatus
            , Guid
            , TransactionID
            , MilestoneID
            , ActivityID
            , Net
            , Vat
            , Gross
            , VatRate
            , Description
            , JobPaymentStageId
            , InvoiceRequestItemId
            , RIBAStageId
            , Qty
            , VatCodeID
        )
        VALUES
        (
              1
            , @Guid
            , @TransactionID
            , ISNULL(@MilestoneID, -1)
            , ISNULL(@ActivityID, -1)
            , @Net
            , @Vat
            , @Gross
            , @VatRate
            , ISNULL(@Description, N'')
            , ISNULL(@JobPaymentStageID, -1)
            , ISNULL(@InvoiceRequestItemID, -1)
            , ISNULL(@RIBAStageID, -1)
            , @Qty
            , @VatCodeID
        );
    END
    ELSE
    BEGIN
        UPDATE td
        SET
              td.MilestoneID = ISNULL(@MilestoneID, -1)
            , td.ActivityID = ISNULL(@ActivityID, -1)
            , td.Net = @Net
            , td.Vat = @Vat
            , td.Gross = @Gross
            , td.VatRate = @VatRate
            , td.Description = ISNULL(@Description, N'')
            , td.JobPaymentStageId = ISNULL(@JobPaymentStageID, -1)
            , td.InvoiceRequestItemId = ISNULL(@InvoiceRequestItemID, -1)
            , td.RIBAStageId = ISNULL(@RIBAStageID, -1)
            , td.Qty = @Qty
            , td.VatCodeID = @VatCodeID
        FROM SFin.TransactionDetails AS td
        WHERE td.Guid = @Guid
          AND td.RowStatus NOT IN (0, 254);
    END;
END;
GO

GO

