CREATE OR ALTER PROCEDURE [SMigration].[OnboardingEntityScope_Seed]
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Seed TABLE
    (
        Guid UNIQUEIDENTIFIER NOT NULL,
        Code NVARCHAR(100) NOT NULL PRIMARY KEY,
        Name NVARCHAR(200) NOT NULL,
        StageTableName SYSNAME NOT NULL,
        DisplayOrder INT NOT NULL,
        DefaultSelected BIT NOT NULL,
        CanDeselect BIT NOT NULL,
        IsRequired BIT NOT NULL,
        RequiredDependencyCodes NVARCHAR(1000) NOT NULL,
        Description NVARCHAR(500) NOT NULL,
        Category NVARCHAR(80) NOT NULL,
        ScopeType NVARCHAR(40) NOT NULL,
        IsImplemented BIT NOT NULL,
        IsSupportData BIT NOT NULL,
        HandlerKey NVARCHAR(100) NOT NULL,
        PrimaryEntityTypeName NVARCHAR(250) NULL,
        SourceSchemaName SYSNAME NOT NULL,
        SourceTableName SYSNAME NOT NULL
    );

    /*
        R2C terminology:
        - OnBoarding scope rows are migration buckets selected per run.
        - SCore.EntityTypes.IsOnBoarding is only an eligibility flag for additional future/configured record types.
        - Physical tables are implementation detail and may be support-only.

        This seed deliberately does not update SCore.EntityTypes.IsOnBoarding.
    */
    INSERT INTO @Seed
    (
        Guid,
        Code,
        Name,
        StageTableName,
        DisplayOrder,
        DefaultSelected,
        CanDeselect,
        IsRequired,
        RequiredDependencyCodes,
        Description,
        Category,
        ScopeType,
        IsImplemented,
        IsSupportData,
        HandlerKey,
        PrimaryEntityTypeName,
        SourceSchemaName,
        SourceTableName
    )
    VALUES
        ('34e5fb6d-878d-4f63-b74f-771eeb243501', N'Groups', N'Groups', N'SMigration.Onboarding_Groups', 10, 1, 1, 0, N'', N'Security groups required by users, organisational units and workflow notification rules.', N'Access Foundation', N'OnBoardingBucket', 1, 0, N'Groups', N'Groups', N'SCore', N'Groups'),
        ('d791485d-45d6-4282-ad62-ee594299e59c', N'OrganisationalUnits', N'Organisational Units', N'SMigration.Onboarding_OrganisationalUnits', 20, 1, 1, 0, N'Groups', N'Business unit and child organisational unit structure.', N'Access Foundation', N'OnBoardingBucket', 1, 0, N'OrganisationalUnits', N'OrganisationalUnits', N'SCore', N'OrganisationalUnits'),
        ('363c6fd4-2712-4841-913f-bc8cc303f2d8', N'Identities', N'Users / Identities', N'SMigration.Onboarding_Identities', 30, 1, 1, 0, N'OrganisationalUnits', N'User identity records linked to source organisational units.', N'Access Foundation', N'OnBoardingBucket', 1, 0, N'Identities', N'Identities', N'SCore', N'Identities'),
        ('2ee2d088-49f7-42a5-b0b0-28f0d82d3320', N'UserGroups', N'User Group Memberships', N'SMigration.Onboarding_UserGroups', 40, 1, 1, 0, N'Groups,Identities', N'User-to-group memberships for staged identities.', N'Access Foundation', N'OnBoardingBucket', 1, 0, N'UserGroups', N'UserGroups', N'SCore', N'UserGroups'),

        ('4c0e8423-d31d-4f4c-a9cf-e42f50fb7421', N'Workflows', N'Workflows', N'SMigration.Onboarding_Workflows', 100, 1, 1, 0, N'OrganisationalUnits', N'Workflow definitions for the selected business unit.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'Workflows', NULL, N'SCore', N'Workflow'),
        ('b63f1c84-0286-4fdc-8f81-4b18fa468dc5', N'WorkflowStatuses', N'Workflow Statuses', N'SMigration.Onboarding_WorkflowStatuses', 105, 1, 1, 0, N'Workflows', N'Workflow statuses referenced by staged workflows, transitions and notification groups.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'WorkflowStatuses', NULL, N'SCore', N'WorkflowStatus'),
        ('b98b2ef9-2b2d-4f33-a85a-0df8ff4fd9ed', N'WorkflowTransitions', N'Workflow Transitions', N'SMigration.Onboarding_WorkflowTransitions', 108, 1, 1, 0, N'Workflows,WorkflowStatuses', N'Workflow transitions for staged workflow definitions.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'WorkflowTransitions', NULL, N'SCore', N'WorkflowTransition'),
        ('9f1b2e81-9082-4f4a-8d61-22dc9d19df56', N'WorkflowStatusNotificationGroups', N'Workflow Notification Groups', N'SMigration.Onboarding_WorkflowStatusNotificationGroups', 110, 1, 1, 0, N'WorkflowStatuses,Groups', N'Workflow status notification group permissions for staged groups.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'WorkflowStatusNotificationGroups', NULL, N'SCore', N'WorkflowStatusNotificationGroups'),
        ('a7a8edc9-cf6a-4a07-bf42-34c41f317095', N'JobTypes', N'Job Types', N'SMigration.Onboarding_JobTypes', 120, 1, 1, 0, N'OrganisationalUnits', N'Job type setup linked to staged organisational units.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'JobTypes', N'JobTypes', N'SJob', N'JobTypes'),
        ('70245f10-58cd-41d2-9f24-f64e9c5937a1', N'ActivityTypes', N'Activity Types', N'SMigration.Onboarding_ActivityTypes', 130, 1, 1, 0, N'', N'Activity type setup used by job type activity templates.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'ActivityTypes', N'ActivityTypes', N'SJob', N'ActivityTypes'),
        ('0bdbb779-e3a6-4a15-8f05-4db4ce094af3', N'MilestoneTypes', N'Milestone Types', N'SMigration.Onboarding_MilestoneTypes', 140, 1, 1, 0, N'', N'Milestone type setup used by job type milestone templates.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'MilestoneTypes', N'MilestoneTypes', N'SJob', N'MilestoneTypes'),
        ('e811d028-9e2c-4c29-b92a-8296970c3f2f', N'Products', N'Products', N'SMigration.Onboarding_Products', 150, 1, 1, 0, N'JobTypes', N'Product setup linked to created job types.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'Products', N'Products', N'SProd', N'Products'),
        ('71945bc5-a2eb-4d72-bc25-6327a860a8b6', N'JobTypeActivityTypes', N'Job Type Activity Templates', N'SMigration.Onboarding_JobTypeActivityTypes', 160, 1, 1, 0, N'JobTypes,ActivityTypes', N'Job type to activity type template relationships.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'JobTypeActivityTypes', NULL, N'SJob', N'JobTypeActivityTypes'),
        ('9d091c29-b679-4d79-a0d1-d2386ab96976', N'JobTypeMilestoneTemplates', N'Job Type Milestone Templates', N'SMigration.Onboarding_JobTypeMilestoneTemplates', 170, 1, 1, 0, N'JobTypes,MilestoneTypes', N'Job type milestone template relationships.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'JobTypeMilestoneTemplates', NULL, N'SJob', N'JobTypeMilestoneTemplates'),
        ('8f7b257d-1784-4414-89c8-b87092db4744', N'ProductJobActivities', N'Product Job Activity Defaults', N'SMigration.Onboarding_ProductJobActivities', 180, 1, 1, 0, N'Products,JobTypeActivityTypes', N'Product activity defaults linked to products and job type activities.', N'Operational Configuration', N'OnBoardingBucket', 1, 0, N'ProductJobActivities', NULL, N'SProd', N'ProductJobActivities');

    UPDATE supportScope
    SET
        RowStatus = 254,
        IsSupportData = 1,
        IsImplemented = 0,
        ScopeType = N'SupportData',
        Category = N'Internal / Support Data',
        UpdatedUtc = SYSUTCDATETIME()
    FROM SMigration.Onboarding_EntityScope AS supportScope
    WHERE supportScope.Code IN (N'Addresses', N'Contacts')
      AND supportScope.StageTableName IN (N'SMigration.Onboarding_Addresses', N'SMigration.Onboarding_Contacts');

    UPDATE target
    SET
        RowStatus = 1,
        Name = source.Name,
        StageTableName = source.StageTableName,
        DisplayOrder = source.DisplayOrder,
        DefaultSelected = source.DefaultSelected,
        CanDeselect = source.CanDeselect,
        IsRequired = source.IsRequired,
        RequiredDependencyCodes = source.RequiredDependencyCodes,
        Description = source.Description,
        Category = source.Category,
        ScopeType = source.ScopeType,
        IsImplemented = source.IsImplemented,
        IsSupportData = source.IsSupportData,
        HandlerKey = source.HandlerKey,
        PrimaryEntityTypeGuid = entityType.Guid,
        SourceSchemaName = source.SourceSchemaName,
        SourceTableName = source.SourceTableName,
        UpdatedUtc = SYSUTCDATETIME()
    FROM SMigration.Onboarding_EntityScope AS target
    INNER JOIN @Seed AS source
        ON source.Code = target.Code
    OUTER APPLY
    (
        SELECT TOP (1) et.Guid
        FROM SCore.EntityTypes AS et
        WHERE et.RowStatus NOT IN (0,254)
          AND source.PrimaryEntityTypeName IS NOT NULL
          AND et.Name IN (source.PrimaryEntityTypeName, REPLACE(source.PrimaryEntityTypeName, N' ', N''))
        ORDER BY et.ID
    ) AS entityType;

    DECLARE
        @Guid UNIQUEIDENTIFIER,
        @Code NVARCHAR(100),
        @Name NVARCHAR(200),
        @StageTableName SYSNAME,
        @DisplayOrder INT,
        @DefaultSelected BIT,
        @CanDeselect BIT,
        @IsRequired BIT,
        @RequiredDependencyCodes NVARCHAR(1000),
        @Description NVARCHAR(500),
        @Category NVARCHAR(80),
        @ScopeType NVARCHAR(40),
        @IsImplemented BIT,
        @IsSupportData BIT,
        @HandlerKey NVARCHAR(100),
        @PrimaryEntityTypeGuid UNIQUEIDENTIFIER,
        @SourceSchemaName SYSNAME,
        @SourceTableName SYSNAME;

    DECLARE seed_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            source.Guid,
            source.Code,
            source.Name,
            source.StageTableName,
            source.DisplayOrder,
            source.DefaultSelected,
            source.CanDeselect,
            source.IsRequired,
            source.RequiredDependencyCodes,
            source.Description,
            source.Category,
            source.ScopeType,
            source.IsImplemented,
            source.IsSupportData,
            source.HandlerKey,
            entityType.Guid,
            source.SourceSchemaName,
            source.SourceTableName
        FROM @Seed AS source
        OUTER APPLY
        (
            SELECT TOP (1) et.Guid
            FROM SCore.EntityTypes AS et
            WHERE et.RowStatus NOT IN (0,254)
              AND source.PrimaryEntityTypeName IS NOT NULL
              AND et.Name IN (source.PrimaryEntityTypeName, REPLACE(source.PrimaryEntityTypeName, N' ', N''))
            ORDER BY et.ID
        ) AS entityType
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM SMigration.Onboarding_EntityScope AS existing
            WHERE existing.Code = source.Code
        )
        ORDER BY source.DisplayOrder;

    OPEN seed_cursor;
    FETCH NEXT FROM seed_cursor INTO @Guid, @Code, @Name, @StageTableName, @DisplayOrder, @DefaultSelected, @CanDeselect, @IsRequired, @RequiredDependencyCodes, @Description, @Category, @ScopeType, @IsImplemented, @IsSupportData, @HandlerKey, @PrimaryEntityTypeGuid, @SourceSchemaName, @SourceTableName;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @Guid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_EntityScope';

        INSERT INTO SMigration.Onboarding_EntityScope
        (
            Guid,
            RowStatus,
            Code,
            Name,
            StageTableName,
            DisplayOrder,
            DefaultSelected,
            CanDeselect,
            IsRequired,
            RequiredDependencyCodes,
            Description,
            Category,
            ScopeType,
            IsImplemented,
            IsSupportData,
            HandlerKey,
            PrimaryEntityTypeGuid,
            SourceSchemaName,
            SourceTableName,
            CreatedUtc,
            UpdatedUtc
        )
        VALUES
        (
            @Guid,
            1,
            @Code,
            @Name,
            @StageTableName,
            @DisplayOrder,
            @DefaultSelected,
            @CanDeselect,
            @IsRequired,
            @RequiredDependencyCodes,
            @Description,
            @Category,
            @ScopeType,
            @IsImplemented,
            @IsSupportData,
            @HandlerKey,
            @PrimaryEntityTypeGuid,
            @SourceSchemaName,
            @SourceTableName,
            SYSUTCDATETIME(),
            SYSUTCDATETIME()
        );

        FETCH NEXT FROM seed_cursor INTO @Guid, @Code, @Name, @StageTableName, @DisplayOrder, @DefaultSelected, @CanDeselect, @IsRequired, @RequiredDependencyCodes, @Description, @Category, @ScopeType, @IsImplemented, @IsSupportData, @HandlerKey, @PrimaryEntityTypeGuid, @SourceSchemaName, @SourceTableName;
    END;

    CLOSE seed_cursor;
    DEALLOCATE seed_cursor;

    /* Discover only entity types explicitly approved for OnBoarding as configured-only candidate rows. */
    ;WITH CandidateEntityHobts AS
    (
        SELECT
            et.Guid AS EntityTypeGuid,
            et.Name AS EntityTypeName,
            eh.SchemaName,
            eh.ObjectName,
            ROW_NUMBER() OVER
            (
                PARTITION BY et.Guid
                ORDER BY
                    CASE WHEN eh.IsMainHoBT = 1 THEN 0 ELSE 1 END,
                    eh.SchemaName,
                    eh.ObjectName,
                    eh.ID
            ) AS HoBTRowNumber
        FROM SCore.EntityTypes AS et
        INNER JOIN SCore.EntityHobts AS eh
            ON eh.EntityTypeID = et.ID
           AND eh.RowStatus NOT IN (0,254)
        WHERE et.RowStatus NOT IN (0,254)
          AND ISNULL(et.IsMetaData, 0) = 0
          AND ISNULL(et.IsOnBoarding, 0) = 1
          AND ISNULL(et.Name, N'') <> N''
          AND et.Name NOT IN
          (
              N'Addresses',
              N'Contacts',
              N'Groups',
              N'Identities',
              N'Products',
              N'OrganisationalUnits',
              N'Organisational Units',
              N'UserGroups',
              N'User Groups',
              N'JobTypes',
              N'Job Types',
              N'ActivityTypes',
              N'Activity Types',
              N'MilestoneTypes',
              N'Milestone Types'
          )
          AND ISNULL(eh.SchemaName, N'') <> N''
          AND ISNULL(eh.ObjectName, N'') <> N''
    ),
    ChosenEntityHobts AS
    (
        SELECT
            candidate.EntityTypeGuid,
            candidate.EntityTypeName,
            candidate.SchemaName,
            candidate.ObjectName
        FROM CandidateEntityHobts AS candidate
        WHERE candidate.HoBTRowNumber = 1
    ),
    DiscoverySource AS
    (
        SELECT
            chosen.EntityTypeGuid,
            LEFT(chosen.EntityTypeName, 100) AS ScopeCode,
            LEFT(chosen.EntityTypeName, 200) AS ScopeName,
            CONVERT(NVARCHAR(128), LEFT(CONCAT(chosen.SchemaName, N'.', chosen.ObjectName), 128)) AS StageTableName,
            10000 + ROW_NUMBER() OVER (ORDER BY chosen.EntityTypeName, chosen.SchemaName, chosen.ObjectName) AS DisplayOrder,
            LEFT(CONCAT(N'EntityType is marked IsOnBoarding = 1 and is eligible for future OnBoarding support from ', chosen.SchemaName, N'.', chosen.ObjectName, N'. It is persisted in run scope, but has no staging/apply handler yet.'), 500) AS Description,
            CONVERT(CHAR(32), HASHBYTES(N'MD5', CONCAT(N'SMigration.Onboarding_EntityScope:', CONVERT(NVARCHAR(36), chosen.EntityTypeGuid))), 2) AS GuidHash,
            chosen.SchemaName,
            chosen.ObjectName
        FROM ChosenEntityHobts AS chosen
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM @Seed AS seed
            WHERE seed.Code = chosen.EntityTypeName
               OR seed.SourceSchemaName + N'.' + seed.SourceTableName = chosen.SchemaName + N'.' + chosen.ObjectName
        )
    )
    SELECT
        CONVERT(UNIQUEIDENTIFIER, STUFF(STUFF(STUFF(STUFF(source.GuidHash, 21, 0, N'-'), 17, 0, N'-'), 13, 0, N'-'), 9, 0, N'-')) AS ScopeGuid,
        source.ScopeCode,
        source.ScopeName,
        source.StageTableName,
        source.DisplayOrder,
        source.Description,
        source.EntityTypeGuid,
        source.SchemaName,
        source.ObjectName
    INTO #OnboardingEligibleEntityScope
    FROM DiscoverySource AS source;

    UPDATE existing
    SET
        RowStatus = 1,
        Name = eligible.ScopeName,
        StageTableName = eligible.StageTableName,
        DisplayOrder = eligible.DisplayOrder,
        DefaultSelected = 1,
        CanDeselect = 1,
        IsRequired = 0,
        RequiredDependencyCodes = N'',
        Description = eligible.Description,
        Category = N'Additional Eligible Record Types',
        ScopeType = N'EligibleEntityType',
        IsImplemented = 0,
        IsSupportData = 0,
        HandlerKey = N'',
        PrimaryEntityTypeGuid = eligible.EntityTypeGuid,
        SourceSchemaName = eligible.SchemaName,
        SourceTableName = eligible.ObjectName,
        UpdatedUtc = SYSUTCDATETIME()
    FROM SMigration.Onboarding_EntityScope AS existing
    INNER JOIN #OnboardingEligibleEntityScope AS eligible
        ON existing.Code = eligible.ScopeCode;

    DECLARE
        @DiscoveredGuid UNIQUEIDENTIFIER,
        @DiscoveredCode NVARCHAR(100),
        @DiscoveredName NVARCHAR(200),
        @DiscoveredStageTableName SYSNAME,
        @DiscoveredDisplayOrder INT,
        @DiscoveredDescription NVARCHAR(500),
        @DiscoveredEntityTypeGuid UNIQUEIDENTIFIER,
        @DiscoveredSchemaName SYSNAME,
        @DiscoveredObjectName SYSNAME;

    DECLARE discovered_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            eligible.ScopeGuid,
            eligible.ScopeCode,
            eligible.ScopeName,
            eligible.StageTableName,
            eligible.DisplayOrder,
            eligible.Description,
            eligible.EntityTypeGuid,
            eligible.SchemaName,
            eligible.ObjectName
        FROM #OnboardingEligibleEntityScope AS eligible
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM SMigration.Onboarding_EntityScope AS existing
            WHERE existing.Code = eligible.ScopeCode
        )
        ORDER BY
            eligible.DisplayOrder,
            eligible.ScopeCode;

    OPEN discovered_cursor;
    FETCH NEXT FROM discovered_cursor INTO @DiscoveredGuid, @DiscoveredCode, @DiscoveredName, @DiscoveredStageTableName, @DiscoveredDisplayOrder, @DiscoveredDescription, @DiscoveredEntityTypeGuid, @DiscoveredSchemaName, @DiscoveredObjectName;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @DiscoveredGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_EntityScope';

        INSERT INTO SMigration.Onboarding_EntityScope
        (
            Guid,
            RowStatus,
            Code,
            Name,
            StageTableName,
            DisplayOrder,
            DefaultSelected,
            CanDeselect,
            IsRequired,
            RequiredDependencyCodes,
            Description,
            Category,
            ScopeType,
            IsImplemented,
            IsSupportData,
            HandlerKey,
            PrimaryEntityTypeGuid,
            SourceSchemaName,
            SourceTableName,
            CreatedUtc,
            UpdatedUtc
        )
        VALUES
        (
            @DiscoveredGuid,
            1,
            @DiscoveredCode,
            @DiscoveredName,
            @DiscoveredStageTableName,
            @DiscoveredDisplayOrder,
            1,
            1,
            0,
            N'',
            @DiscoveredDescription,
            N'Additional Eligible Record Types',
            N'EligibleEntityType',
            0,
            0,
            N'',
            @DiscoveredEntityTypeGuid,
            @DiscoveredSchemaName,
            @DiscoveredObjectName,
            SYSUTCDATETIME(),
            SYSUTCDATETIME()
        );

        FETCH NEXT FROM discovered_cursor INTO @DiscoveredGuid, @DiscoveredCode, @DiscoveredName, @DiscoveredStageTableName, @DiscoveredDisplayOrder, @DiscoveredDescription, @DiscoveredEntityTypeGuid, @DiscoveredSchemaName, @DiscoveredObjectName;
    END;

    CLOSE discovered_cursor;
    DEALLOCATE discovered_cursor;

    UPDATE obsolete
    SET
        RowStatus = 254,
        UpdatedUtc = SYSUTCDATETIME()
    FROM SMigration.Onboarding_EntityScope AS obsolete
    WHERE obsolete.RowStatus NOT IN (0,254)
      AND obsolete.ScopeType = N'EligibleEntityType'
      AND NOT EXISTS
      (
          SELECT 1
          FROM #OnboardingEligibleEntityScope AS eligible
          WHERE eligible.ScopeCode = obsolete.Code
      );

    DROP TABLE #OnboardingEligibleEntityScope;

    DECLARE ensure_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT es.Guid
        FROM SMigration.Onboarding_EntityScope AS es
        WHERE es.RowStatus NOT IN (0,254);

    OPEN ensure_cursor;
    FETCH NEXT FROM ensure_cursor INTO @Guid;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @Guid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_EntityScope';

        FETCH NEXT FROM ensure_cursor INTO @Guid;
    END;

    CLOSE ensure_cursor;
    DEALLOCATE ensure_cursor;
END;
GO

GO

/* Deploy StoredProcedure SMigration.OnboardingImport_Apply using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingImport_Apply.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SMigration.OnboardingImport_Apply
    Source schema hash : 108C77D888CD1207C55C58A7560448AD0A4499262ACFE63A06D3DDFAB66C03B2
    Definition SHA-256 : C17FE136B9F7877B7330B974DE3A19986ED7030752DCA7E6D32E603AEB0D14D4

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* ================================================================================================
   Apply import

   CymBuild-safe apply rules:
   - Preview mode performs no writes.
   - Real apply is transaction protected and rollback-safe.
   - Every true insert creates/uses SCore.DataObjects via SCore.UpsertDataObject first.
   - Sentinel GUIDs are ignored.
   - Business-key collisions are updated/remapped/skipped instead of inserted as duplicates.
   - Relationship/bridge tables are de-duplicated by their natural key before insert.
   ================================================================================================ */
CREATE OR ALTER PROCEDURE [SMigration].[OnboardingImport_Apply]
    @RunGuid UNIQUEIDENTIFIER,
    @AllowWarnings BIT = 1,
    @PreviewOnly BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE
        @Guid UNIQUEIDENTIFIER,
        @IsInsert BIT,
        @cnt INT,
        @StartedTran BIT = 0;

    DECLARE @ZeroGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000';

    DECLARE
        @SourceBusinessUnitGroupGuid UNIQUEIDENTIFIER = NULL,
        @SourceBusinessUnitOrganisationalUnitGuid UNIQUEIDENTIFIER = NULL,
        @TargetBusinessUnitGroupGuid UNIQUEIDENTIFIER = NULL,
        @TargetBusinessUnitOrganisationalUnitGuid UNIQUEIDENTIFIER = NULL,
        @SourceBusinessUnitGroupName NVARCHAR(250) = NULL;

    SELECT
        @SourceBusinessUnitGroupGuid = runHeader.SourceBusinessUnitGroupGuid,
        @SourceBusinessUnitOrganisationalUnitGuid = runHeader.SourceBusinessUnitOrganisationalUnitGuid
    FROM SMigration.Onboarding_Run AS runHeader
    WHERE runHeader.RunGuid = @RunGuid;

    EXEC SMigration.OnboardingValidate @RunGuid = @RunGuid;

    IF EXISTS
    (
        SELECT 1
        FROM SMigration.Onboarding_ValidationIssues
        WHERE RunGuid = @RunGuid
          AND Severity = N'Error'
    )
    BEGIN
        ;THROW 60000, N'SMigration validation failed. Resolve errors before import.', 1;
    END;

    IF @AllowWarnings = 0
       AND EXISTS
       (
           SELECT 1
           FROM SMigration.Onboarding_ValidationIssues
           WHERE RunGuid = @RunGuid
             AND Severity = N'Warning'
       )
    BEGIN
        ;THROW 60000, N'SMigration validation contains warnings and @AllowWarnings = 0.', 1;
    END;

    IF @PreviewOnly = 1
    BEGIN
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'All', N'Preview', 0, N'Preview only; no changes applied.';
        EXEC SMigration.OnboardingReport @RunGuid = @RunGuid;
        RETURN;
    END;

    BEGIN TRY
        IF @@TRANCOUNT = 0
        BEGIN
            SET @StartedTran = 1;
            BEGIN TRAN;
        END;

        EXEC SMigration.OnboardingRunStageSelection_ApplyToStage @RunGuid = @RunGuid;

        /* ========================================================================================
           Shared remap tables
           ======================================================================================== */
        DECLARE @WorkflowGuidRemap TABLE
        (
            SourceWorkflowGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetWorkflowGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @WorkflowStatusGuidRemap TABLE
        (
            SourceWorkflowStatusGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetWorkflowStatusGuid UNIQUEIDENTIFIER NOT NULL
        );
        
        DECLARE @GroupGuidRemap TABLE
        (
            SourceGroupGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetGroupGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @AddressGuidRemap TABLE
        (
            SourceAddressGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetAddressGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @ContactGuidRemap TABLE
        (
            SourceContactGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetContactGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @OrganisationalUnitGuidRemap TABLE
        (
            SourceOrganisationalUnitGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetOrganisationalUnitGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @IdentityGuidRemap TABLE
        (
            SourceIdentityGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetIdentityGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @JobTypeGuidRemap TABLE
        (
            SourceJobTypeGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetJobTypeGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @ActivityTypeGuidRemap TABLE
        (
            SourceActivityTypeGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetActivityTypeGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @MilestoneTypeGuidRemap TABLE
        (
            SourceMilestoneTypeGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetMilestoneTypeGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @JobTypeActivityTypeGuidRemap TABLE
        (
            SourceJobTypeActivityTypeGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetJobTypeActivityTypeGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @JobTypeMilestoneTemplateGuidRemap TABLE
        (
            SourceJobTypeMilestoneTemplateGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetJobTypeMilestoneTemplateGuid UNIQUEIDENTIFIER NOT NULL
        );

        DECLARE @ProductGuidRemap TABLE
        (
            SourceProductGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            TargetProductGuid UNIQUEIDENTIFIER NOT NULL
        );

        /* ========================================================================================
           1. Groups
           Match order:
           1) Guid
           2) Code
           3) Name
           ======================================================================================== */
        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.DirectoryId = s.DirectoryId,
               t.Code = s.Code,
               t.Name = s.Name,
               t.Source = s.Source
        FROM SCore.Groups AS t
        INNER JOIN SMigration.Onboarding_Groups AS s
            ON s.GroupGuid = t.Guid
        WHERE s.RunGuid = @RunGuid
          AND t.ID > 0
          AND s.GroupGuid <> @ZeroGuid;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Groups', N'Update', @cnt, N'Updated groups matched by Guid.';

        INSERT INTO @GroupGuidRemap
        (
            SourceGroupGuid,
            TargetGroupGuid
        )
        SELECT
            s.GroupGuid,
            t.Guid
        FROM SMigration.Onboarding_Groups AS s
        INNER JOIN SCore.Groups AS t
            ON t.ID > 0
           AND t.Guid <> s.GroupGuid
           AND
           (
                NULLIF(LTRIM(RTRIM(s.Code)), N'') IS NOT NULL
                AND LOWER(LTRIM(RTRIM(t.Code))) = LOWER(LTRIM(RTRIM(s.Code)))
           )
        WHERE s.RunGuid = @RunGuid
          AND s.GroupGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.Groups AS x
              WHERE x.Guid = s.GroupGuid
                AND x.ID > 0
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM @GroupGuidRemap AS m
              WHERE m.SourceGroupGuid = s.GroupGuid
          );

        INSERT INTO @GroupGuidRemap
        (
            SourceGroupGuid,
            TargetGroupGuid
        )
        SELECT
            s.GroupGuid,
            t.Guid
        FROM SMigration.Onboarding_Groups AS s
        INNER JOIN SCore.Groups AS t
            ON t.ID > 0
           AND t.Guid <> s.GroupGuid
           AND LOWER(LTRIM(RTRIM(t.Name))) = LOWER(LTRIM(RTRIM(s.Name)))
        WHERE s.RunGuid = @RunGuid
          AND s.GroupGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.Groups AS x
              WHERE x.Guid = s.GroupGuid
                AND x.ID > 0
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM @GroupGuidRemap AS m
              WHERE m.SourceGroupGuid = s.GroupGuid
          );

        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.DirectoryId = s.DirectoryId,
               t.Code = s.Code,
               t.Name = s.Name,
               t.Source = s.Source
        FROM @GroupGuidRemap AS m
        INNER JOIN SMigration.Onboarding_Groups AS s
            ON s.RunGuid = @RunGuid
           AND s.GroupGuid = m.SourceGroupGuid
        INNER JOIN SCore.Groups AS t
            ON t.Guid = m.TargetGroupGuid
           AND t.ID > 0;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Groups', N'Update', @cnt, N'Updated groups matched by Code/Name.';

        DECLARE cur_groups CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.GroupGuid
        FROM SMigration.Onboarding_Groups AS s
        WHERE s.RunGuid = @RunGuid
          AND s.GroupGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.Groups AS t
              WHERE t.Guid = s.GroupGuid
                AND t.ID > 0
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM @GroupGuidRemap AS m
              WHERE m.SourceGroupGuid = s.GroupGuid
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.Groups AS t
              WHERE t.ID > 0
                AND
                (
                    (
                        NULLIF(LTRIM(RTRIM(s.Code)), N'') IS NOT NULL
                        AND LOWER(LTRIM(RTRIM(t.Code))) = LOWER(LTRIM(RTRIM(s.Code)))
                    )
                    OR LOWER(LTRIM(RTRIM(t.Name))) = LOWER(LTRIM(RTRIM(s.Name)))
                )
          );

        OPEN cur_groups;
        FETCH NEXT FROM cur_groups INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC SCore.UpsertDataObject
                @Guid = @Guid,
                @SchemeName = N'SCore',
                @ObjectName = N'Groups',
                @IncludeDefaultSecurity = 0,
                @IsInsert = @IsInsert OUTPUT;


            INSERT INTO SCore.Groups
            (
                RowStatus,
                Guid,
                DirectoryId,
                Code,
                Name,
                Source
            )
            SELECT
                s.RowStatus,
                s.GroupGuid,
                s.DirectoryId,
                s.Code,
                s.Name,
                s.Source
            FROM SMigration.Onboarding_Groups AS s
            WHERE s.RunGuid = @RunGuid
              AND s.GroupGuid = @Guid;

            SET @cnt += @@ROWCOUNT;

            FETCH NEXT FROM cur_groups INTO @Guid;
        END;

        CLOSE cur_groups;
        DEALLOCATE cur_groups;

        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Groups', N'Insert', @cnt, N'Inserted new groups only.';

        UPDATE ug
           SET ug.GroupGuid = m.TargetGroupGuid
        FROM SMigration.Onboarding_UserGroups AS ug
        INNER JOIN @GroupGuidRemap AS m
            ON m.SourceGroupGuid = ug.GroupGuid
        WHERE ug.RunGuid = @RunGuid;

        UPDATE wsng
           SET wsng.GroupGuid = m.TargetGroupGuid
        FROM SMigration.Onboarding_WorkflowStatusNotificationGroups AS wsng
        INNER JOIN @GroupGuidRemap AS m
            ON m.SourceGroupGuid = wsng.GroupGuid
        WHERE wsng.RunGuid = @RunGuid;

        UPDATE ou
           SET ou.DefaultSecurityGroupGuid = m.TargetGroupGuid
        FROM SMigration.Onboarding_OrganisationalUnits AS ou
        INNER JOIN @GroupGuidRemap AS m
            ON m.SourceGroupGuid = ou.DefaultSecurityGroupGuid
        WHERE ou.RunGuid = @RunGuid;

        /*
           R4 F4 parent OU identity-map foundation.
           A selected source business unit may already exist in the target under a different Guid.
           Resolve that root by: exact OU Guid, mapped/default security group, then a conservative name fallback.
           This lets child OUs map to the existing target parent rather than forcing a same-Guid parent.
        */
        SELECT TOP (1)
            @TargetBusinessUnitGroupGuid = m.TargetGroupGuid
        FROM @GroupGuidRemap AS m
        WHERE m.SourceGroupGuid = @SourceBusinessUnitGroupGuid;

        IF @TargetBusinessUnitGroupGuid IS NULL
           AND EXISTS
           (
               SELECT 1
               FROM SCore.Groups AS existingBusinessUnitGroup
               WHERE existingBusinessUnitGroup.Guid = @SourceBusinessUnitGroupGuid
                 AND existingBusinessUnitGroup.ID > 0
           )
        BEGIN
            SET @TargetBusinessUnitGroupGuid = @SourceBusinessUnitGroupGuid;
        END;

        SELECT TOP (1)
            @SourceBusinessUnitGroupName = sourceBusinessUnitGroup.Name
        FROM SMigration.Onboarding_Groups AS sourceBusinessUnitGroup
        WHERE sourceBusinessUnitGroup.RunGuid = @RunGuid
          AND sourceBusinessUnitGroup.GroupGuid = @SourceBusinessUnitGroupGuid;

        SELECT TOP (1)
            @TargetBusinessUnitOrganisationalUnitGuid = targetBusinessUnitOu.Guid
        FROM SCore.OrganisationalUnits AS targetBusinessUnitOu
        WHERE targetBusinessUnitOu.Guid = @SourceBusinessUnitOrganisationalUnitGuid
          AND targetBusinessUnitOu.ID > 0
        ORDER BY
            CASE WHEN targetBusinessUnitOu.RowStatus NOT IN (0, 254) THEN 0 ELSE 1 END,
            targetBusinessUnitOu.ID;

        IF @TargetBusinessUnitOrganisationalUnitGuid IS NULL
           AND @TargetBusinessUnitGroupGuid IS NOT NULL
           AND @TargetBusinessUnitGroupGuid <> @ZeroGuid
        BEGIN
            SELECT TOP (1)
                @TargetBusinessUnitOrganisationalUnitGuid = targetBusinessUnitOu.Guid
            FROM SCore.OrganisationalUnits AS targetBusinessUnitOu
            INNER JOIN SCore.Groups AS targetBusinessUnitGroup
                ON targetBusinessUnitGroup.ID = targetBusinessUnitOu.DefaultSecurityGroupId
            WHERE targetBusinessUnitGroup.Guid = @TargetBusinessUnitGroupGuid
              AND targetBusinessUnitOu.ID > 0
            ORDER BY
                CASE WHEN targetBusinessUnitOu.RowStatus NOT IN (0, 254) THEN 0 ELSE 1 END,
                targetBusinessUnitOu.ID;
        END;

        IF @TargetBusinessUnitOrganisationalUnitGuid IS NULL
           AND NULLIF(LTRIM(RTRIM(ISNULL(@SourceBusinessUnitGroupName, N''))), N'') IS NOT NULL
        BEGIN
            SELECT TOP (1)
                @TargetBusinessUnitOrganisationalUnitGuid = targetBusinessUnitOu.Guid
            FROM SCore.OrganisationalUnits AS targetBusinessUnitOu
            WHERE targetBusinessUnitOu.ID > 0
              AND LOWER(LTRIM(RTRIM(targetBusinessUnitOu.Name))) = LOWER(LTRIM(RTRIM(@SourceBusinessUnitGroupName)))
            ORDER BY
                CASE WHEN targetBusinessUnitOu.RowStatus NOT IN (0, 254) THEN 0 ELSE 1 END,
                targetBusinessUnitOu.ID;
        END;

        IF @SourceBusinessUnitOrganisationalUnitGuid IS NOT NULL
           AND @SourceBusinessUnitOrganisationalUnitGuid <> @ZeroGuid
           AND @TargetBusinessUnitOrganisationalUnitGuid IS NOT NULL
           AND @TargetBusinessUnitOrganisationalUnitGuid <> @ZeroGuid
        BEGIN
            INSERT INTO @OrganisationalUnitGuidRemap
            (
                SourceOrganisationalUnitGuid,
                TargetOrganisationalUnitGuid
            )
            SELECT
                @SourceBusinessUnitOrganisationalUnitGuid,
                @TargetBusinessUnitOrganisationalUnitGuid
            WHERE NOT EXISTS
            (
                SELECT 1
                FROM @OrganisationalUnitGuidRemap AS existingBusinessUnitMap
                WHERE existingBusinessUnitMap.SourceOrganisationalUnitGuid = @SourceBusinessUnitOrganisationalUnitGuid
            );

            EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'OrganisationalUnits', N'Map', 1, N'Mapped source business unit OU to existing target OU for parent resolution.';
        END;

        /* ========================================================================================
           2. Addresses
           Guid-safe only, with sentinel protection.
           ======================================================================================== */
        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.AddressNumber = s.AddressNumber,
               t.Name = s.Name,
               t.Number = s.Number,
               t.AddressLine1 = s.AddressLine1,
               t.AddressLine2 = s.AddressLine2,
               t.AddressLine3 = s.AddressLine3,
               t.Town = s.Town,
               t.CountyID = c.ID,
               t.Postcode = s.Postcode,
               t.CountryID = co.ID,
               t.LegacySystemID = s.LegacySystemID,
               t.FormattedAddressCR = SCore.FormatAddress(N'', s.Number, s.AddressLine1, s.AddressLine2, s.AddressLine3, s.Town, c.Name, s.Postcode, CHAR(13)),
               t.FormattedAddressComma = SCore.FormatAddress(N'', s.Number, s.AddressLine1, s.AddressLine2, s.AddressLine3, s.Town, c.Name, s.Postcode, N',')
        FROM SCrm.Addresses AS t
        INNER JOIN SMigration.Onboarding_Addresses AS s
            ON s.AddressGuid = t.Guid
        LEFT JOIN SCrm.Counties AS c
            ON c.Guid = s.CountyGuid
        LEFT JOIN SCrm.Countries AS co
            ON co.Guid = s.CountryGuid
        WHERE s.RunGuid = @RunGuid
          AND t.ID > 0
          AND s.AddressGuid <> @ZeroGuid;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Addresses', N'Update', @cnt, N'Updated addresses matched by Guid.';

        DECLARE cur_addr CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.AddressGuid
        FROM SMigration.Onboarding_Addresses AS s
        WHERE s.RunGuid = @RunGuid
          AND s.AddressGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCrm.Addresses AS t
              WHERE t.Guid = s.AddressGuid
                AND t.ID > 0
          );

        OPEN cur_addr;
        FETCH NEXT FROM cur_addr INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC SCore.UpsertDataObject
                @Guid = @Guid,
                @SchemeName = N'SCrm',
                @ObjectName = N'Addresses',
                @IncludeDefaultSecurity = 0,
                @IsInsert = @IsInsert OUTPUT;

            INSERT INTO SCrm.Addresses
            (
                RowStatus,
                Guid,
                AddressNumber,
                Name,
                Number,
                AddressLine1,
                AddressLine2,
                AddressLine3,
                Town,
                CountyID,
                Postcode,
                CountryID,
                LegacyID,
                FormattedAddressCR,
                FormattedAddressComma,
                LegacySystemID
            )
            SELECT
                s.RowStatus,
                s.AddressGuid,
                s.AddressNumber,
                s.Name,
                s.Number,
                s.AddressLine1,
                s.AddressLine2,
                s.AddressLine3,
                s.Town,
                c.ID,
                s.Postcode,
                co.ID,
                NULL,
                SCore.FormatAddress(N'', s.Number, s.AddressLine1, s.AddressLine2, s.AddressLine3, s.Town, c.Name, s.Postcode, CHAR(13)),
                SCore.FormatAddress(N'', s.Number, s.AddressLine1, s.AddressLine2, s.AddressLine3, s.Town, c.Name, s.Postcode, N','),
                s.LegacySystemID
            FROM SMigration.Onboarding_Addresses AS s
            LEFT JOIN SCrm.Counties AS c
                ON c.Guid = s.CountyGuid
            LEFT JOIN SCrm.Countries AS co
                ON co.Guid = s.CountryGuid
            WHERE s.RunGuid = @RunGuid
              AND s.AddressGuid = @Guid;

            SET @cnt += @@ROWCOUNT;

            FETCH NEXT FROM cur_addr INTO @Guid;
        END;

        CLOSE cur_addr;
        DEALLOCATE cur_addr;

        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Addresses', N'Insert', @cnt, N'Inserted new addresses only.';

        /* ========================================================================================
           3. Contacts
           Guid-safe only.
           ======================================================================================== */
        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.PrimaryAccountID = a.ID,
               t.PrimaryAddressID = addr.ID,
               t.FirstName = s.FirstName,
               t.Initials = s.Initials,
               t.Surname = s.Surname,
               t.PostNominals = s.PostNominals,
               t.TitleId = tt.ID,
               t.DisplayName = s.DisplayName,
               t.IsPerson = s.IsPerson,
               t.PositionID = p.ID,
               t.LegacySystemID = s.LegacySystemID
        FROM SCrm.Contacts AS t
        INNER JOIN SMigration.Onboarding_Contacts AS s
            ON s.ContactGuid = t.Guid
        LEFT JOIN SCrm.Accounts AS a
            ON a.Guid = s.PrimaryAccountGuid
        INNER JOIN SCrm.Addresses AS addr
            ON addr.Guid = s.PrimaryAddressGuid
        LEFT JOIN SCrm.ContactTitles AS tt
            ON tt.Guid = s.TitleGuid
        LEFT JOIN SCrm.ContactPositions AS p
            ON p.Guid = s.PositionGuid
        WHERE s.RunGuid = @RunGuid
          AND t.ID > 0
          AND s.ContactGuid <> @ZeroGuid;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Contacts', N'Update', @cnt, N'Updated contacts matched by Guid.';

        DECLARE cur_contact CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.ContactGuid
        FROM SMigration.Onboarding_Contacts AS s
        WHERE s.RunGuid = @RunGuid
          AND s.ContactGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCrm.Contacts AS t
              WHERE t.Guid = s.ContactGuid
                AND t.ID > 0
          );

        OPEN cur_contact;
        FETCH NEXT FROM cur_contact INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC SCore.UpsertDataObject
                @Guid = @Guid,
                @SchemeName = N'SCrm',
                @ObjectName = N'Contacts',
                @IncludeDefaultSecurity = 0,
                @IsInsert = @IsInsert OUTPUT;

            INSERT INTO SCrm.Contacts
            (
                RowStatus,
                Guid,
                PrimaryAccountID,
                PrimaryAddressID,
                FirstName,
                Initials,
                Surname,
                PostNominals,
                TitleId,
                DisplayName,
                IsPerson,
                PositionID,
                LegacyID,
                LegacySystemID
            )
            SELECT
                s.RowStatus,
                s.ContactGuid,
                a.ID,
                addr.ID,
                s.FirstName,
                s.Initials,
                s.Surname,
                s.PostNominals,
                tt.ID,
                s.DisplayName,
                s.IsPerson,
                p.ID,
                NULL,
                s.LegacySystemID
            FROM SMigration.Onboarding_Contacts AS s
            LEFT JOIN SCrm.Accounts AS a
                ON a.Guid = s.PrimaryAccountGuid
            INNER JOIN SCrm.Addresses AS addr
                ON addr.Guid = s.PrimaryAddressGuid
            LEFT JOIN SCrm.ContactTitles AS tt
                ON tt.Guid = s.TitleGuid
            LEFT JOIN SCrm.ContactPositions AS p
                ON p.Guid = s.PositionGuid
            WHERE s.RunGuid = @RunGuid
              AND s.ContactGuid = @Guid;

            SET @cnt += @@ROWCOUNT;

            FETCH NEXT FROM cur_contact INTO @Guid;
        END;

        CLOSE cur_contact;
        DEALLOCATE cur_contact;

        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Contacts', N'Insert', @cnt, N'Inserted new contacts only.';

        /* ========================================================================================
           4. OrganisationalUnits
           Match order:
           1) Guid
           2) Name
           ======================================================================================== */
        DECLARE cur_ou CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.OrganisationalUnitGuid
        FROM SMigration.Onboarding_OrganisationalUnits AS s
        WHERE s.RunGuid = @RunGuid
          AND s.OrganisationalUnitGuid <> @ZeroGuid
        ORDER BY ISNULL(s.OrgLevel, 0), s.Name;

        OPEN cur_ou;
        FETCH NEXT FROM cur_ou INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            DECLARE
                @ParentGuid UNIQUEIDENTIFIER,
                @ParentName NVARCHAR(250),
                @ResolvedParentGuid UNIQUEIDENTIFIER,
                @Name NVARCHAR(250),
                @AddressGuid UNIQUEIDENTIFIER,
                @ContactGuid UNIQUEIDENTIFIER,
                @OfficialAddressGuid UNIQUEIDENTIFIER,
                @OfficialContactGuid UNIQUEIDENTIFIER,
                @DepartmentPrefix NVARCHAR(10),
                @CostCentreCode NVARCHAR(50),
                @DefaultSecurityGroupGuid UNIQUEIDENTIFIER,
                @QuoteThreshold DECIMAL(19, 2),
                @ExistingGuid UNIQUEIDENTIFIER,
                @ApplyOuGuid UNIQUEIDENTIFIER;

            SELECT
                @ParentGuid = s.ParentOrganisationalUnitGuid,
                @ParentName = s.ParentOrganisationalUnitName,
                @Name = s.Name,
                @AddressGuid = s.AddressGuid,
                @ContactGuid = s.ContactGuid,
                @OfficialAddressGuid = s.OfficialAddressGuid,
                @OfficialContactGuid = s.OfficialContactGuid,
                @DepartmentPrefix = s.DepartmentPrefix,
                @CostCentreCode = s.CostCentreCode,
                @DefaultSecurityGroupGuid = s.DefaultSecurityGroupGuid,
                @QuoteThreshold = s.QuoteThreshold
            FROM SMigration.Onboarding_OrganisationalUnits AS s
            WHERE s.RunGuid = @RunGuid
              AND s.OrganisationalUnitGuid = @Guid;

            SET @ResolvedParentGuid = @ParentGuid;

            SELECT
                @ResolvedParentGuid = m.TargetOrganisationalUnitGuid
            FROM @OrganisationalUnitGuidRemap AS m
            WHERE m.SourceOrganisationalUnitGuid = @ParentGuid;

            SELECT
                @DefaultSecurityGroupGuid = m.TargetGroupGuid
            FROM @GroupGuidRemap AS m
            WHERE m.SourceGroupGuid = @DefaultSecurityGroupGuid;

            IF @ResolvedParentGuid IS NOT NULL
               AND @ResolvedParentGuid <> @ZeroGuid
               AND NOT EXISTS
               (
                   SELECT 1
                   FROM SCore.OrganisationalUnits AS parentCheck
                   WHERE parentCheck.Guid = @ResolvedParentGuid
                     AND parentCheck.ID > 0
               )
            BEGIN
                DECLARE @StagedParentName NVARCHAR(250) = NULL;

                SELECT TOP (1)
                    @StagedParentName = parentStage.Name
                FROM SMigration.Onboarding_OrganisationalUnits AS parentStage
                WHERE parentStage.RunGuid = @RunGuid
                  AND parentStage.OrganisationalUnitGuid = @ParentGuid;

                SET @StagedParentName = NULLIF(LTRIM(RTRIM(ISNULL(@StagedParentName, N''))), N'');

                IF @StagedParentName IS NULL
                BEGIN
                    SET @StagedParentName = NULLIF(LTRIM(RTRIM(ISNULL(@ParentName, N''))), N'');
                END;

                IF @StagedParentName IS NOT NULL
                BEGIN
                    SELECT TOP (1)
                        @ResolvedParentGuid = targetParent.Guid
                    FROM SCore.OrganisationalUnits AS targetParent
                    WHERE targetParent.ID > 0
                      AND LOWER(LTRIM(RTRIM(targetParent.Name))) = LOWER(LTRIM(RTRIM(@StagedParentName)))
                    ORDER BY
                        CASE WHEN targetParent.RowStatus NOT IN (0, 254) THEN 0 ELSE 1 END,
                        targetParent.ID;

                    IF @ResolvedParentGuid IS NOT NULL
                       AND @ResolvedParentGuid <> @ZeroGuid
                    BEGIN
                        INSERT INTO @OrganisationalUnitGuidRemap
                        (
                            SourceOrganisationalUnitGuid,
                            TargetOrganisationalUnitGuid
                        )
                        SELECT
                            @ParentGuid,
                            @ResolvedParentGuid
                        WHERE NOT EXISTS
                        (
                            SELECT 1
                            FROM @OrganisationalUnitGuidRemap AS existingParentMap
                            WHERE existingParentMap.SourceOrganisationalUnitGuid = @ParentGuid
                        );
                    END;
                END;
            END;

            IF @ResolvedParentGuid IS NOT NULL
               AND @ResolvedParentGuid <> @ZeroGuid
               AND NOT EXISTS
               (
                   SELECT 1
                   FROM SCore.OrganisationalUnits AS parentCheck
                   WHERE parentCheck.Guid = @ResolvedParentGuid
                     AND parentCheck.ID > 0
               )
               AND @ParentGuid = @SourceBusinessUnitOrganisationalUnitGuid
               AND @TargetBusinessUnitOrganisationalUnitGuid IS NOT NULL
               AND @TargetBusinessUnitOrganisationalUnitGuid <> @ZeroGuid
            BEGIN
                SET @ResolvedParentGuid = @TargetBusinessUnitOrganisationalUnitGuid;
            END;

            SET @ExistingGuid = NULL;

            SELECT TOP (1)
                @ExistingGuid = ou.Guid
            FROM SCore.OrganisationalUnits AS ou
            WHERE ou.Guid = @Guid
              AND ou.ID > 0;

            IF @ExistingGuid IS NULL
            BEGIN
                SELECT TOP (1)
                    @ExistingGuid = ou.Guid
                FROM SCore.OrganisationalUnits AS ou
                WHERE ou.ID > 0
                  AND LOWER(LTRIM(RTRIM(ou.Name))) = LOWER(LTRIM(RTRIM(@Name)))
                ORDER BY
                    CASE WHEN ou.RowStatus NOT IN (0, 254) THEN 0 ELSE 1 END,
                    ou.ID;
            END;

            SET @ApplyOuGuid = ISNULL(@ExistingGuid, @Guid);

            IF @ExistingGuid IS NOT NULL
               AND @ExistingGuid <> @Guid
            BEGIN
                INSERT INTO @OrganisationalUnitGuidRemap
                (
                    SourceOrganisationalUnitGuid,
                    TargetOrganisationalUnitGuid
                )
                SELECT
                    @Guid,
                    @ExistingGuid
                WHERE NOT EXISTS
                (
                    SELECT 1
                    FROM @OrganisationalUnitGuidRemap AS x
                    WHERE x.SourceOrganisationalUnitGuid = @Guid
                );
            END;

            IF @ExistingGuid IS NULL
               AND
               (
                   @ResolvedParentGuid IS NULL
                   OR @ResolvedParentGuid = @ZeroGuid
                   OR NOT EXISTS
                   (
                       SELECT 1
                       FROM SCore.OrganisationalUnits AS parentCheck
                       WHERE parentCheck.Guid = @ResolvedParentGuid
                         AND parentCheck.ID > 0
                   )
               )
            BEGIN
                DECLARE @ParentResolutionMessage NVARCHAR(2048);

                SET @ParentResolutionMessage = CONCAT(
                    N'Unable to apply OrganisationalUnit "', ISNULL(@Name, N''),
                    N'" because its parent organisational unit could not be resolved in the target database. Source parent Guid: ',
                    CONVERT(NVARCHAR(36), ISNULL(@ParentGuid, @ZeroGuid)),
                    CASE
                        WHEN NULLIF(LTRIM(RTRIM(ISNULL(@ParentName, N''))), N'') IS NULL THEN N''
                        ELSE CONCAT(N'. Source parent Name: ', @ParentName)
                    END,
                    N'. Restage this run if the source parent name is missing, select/include the parent OU in this run, or ensure the target has a matching parent OU/default security group mapping before applying.'
                );

                THROW 62431, @ParentResolutionMessage, 1;
            END;

            IF @ExistingGuid IS NULL
               AND EXISTS
               (
                   SELECT 1
                   FROM SCore.DataObjects AS dataObject
                   WHERE dataObject.Guid = @ApplyOuGuid
               )
               AND NOT EXISTS
               (
                   SELECT 1
                   FROM SCore.OrganisationalUnits AS existingOu
                   WHERE existingOu.Guid = @ApplyOuGuid
               )
            BEGIN
                DECLARE
                    @RepairParentId INT,
                    @RepairParentOrgNode HIERARCHYID,
                    @RepairLastChild HIERARCHYID,
                    @RepairNewOrgNode HIERARCHYID,
                    @RepairAddressId INT,
                    @RepairContactId INT,
                    @RepairOfficialAddressId INT,
                    @RepairOfficialContactId INT,
                    @RepairDefaultSecurityGroupId INT;

                SELECT
                    @RepairParentId = parentOu.ID,
                    @RepairParentOrgNode = parentOu.OrgNode
                FROM SCore.OrganisationalUnits AS parentOu
                WHERE parentOu.Guid = @ResolvedParentGuid
                  AND parentOu.ID > 0;

                IF @RepairParentId IS NULL OR @RepairParentOrgNode IS NULL
                BEGIN
                    DECLARE @RepairParentResolutionMessage NVARCHAR(2048);

                    SET @RepairParentResolutionMessage = CONCAT(
                        N'Unable to repair orphan OrganisationalUnit DataObject for "', ISNULL(@Name, N''),
                        N'" because the parent organisational unit could not be resolved in the target database. Source parent Guid: ',
                        CONVERT(NVARCHAR(36), ISNULL(@ParentGuid, @ZeroGuid)),
                        N'. Select/include the parent OU in this run, or ensure the target has a matching parent OU/default security group mapping before applying.'
                    );

                    THROW 62430, @RepairParentResolutionMessage, 1;
                END;

                SELECT @RepairAddressId = addr.ID
                FROM SCrm.Addresses AS addr
                WHERE addr.Guid = @AddressGuid;

                SELECT @RepairContactId = contact.ID
                FROM SCrm.Contacts AS contact
                WHERE contact.Guid = @ContactGuid;

                SELECT @RepairOfficialAddressId = addr.ID
                FROM SCrm.Addresses AS addr
                WHERE addr.Guid = @OfficialAddressGuid;

                SELECT @RepairOfficialContactId = contact.ID
                FROM SCrm.Contacts AS contact
                WHERE contact.Guid = @OfficialContactGuid;

                SELECT @RepairDefaultSecurityGroupId = grp.ID
                FROM SCore.Groups AS grp
                WHERE grp.Guid = @DefaultSecurityGroupGuid;

                SELECT @RepairLastChild = MAX(childOu.OrgNode)
                FROM SCore.OrganisationalUnits AS childOu
                WHERE childOu.OrgNode.GetAncestor(1) = @RepairParentOrgNode;

                SET @RepairNewOrgNode = @RepairParentOrgNode.GetDescendant(@RepairLastChild, NULL);

                INSERT INTO SCore.OrganisationalUnits
                (
                    RowStatus,
                    Guid,
                    Name,
                    AddressId,
                    ContactId,
                    OfficialAddressId,
                    OfficialContactId,
                    DepartmentPrefix,
                    CostCentreCode,
                    DefaultSecurityGroupId,
                    ParentID,
                    OrgNode,
                    QuoteThreshold
                )
                VALUES
                (
                    1,
                    @ApplyOuGuid,
                    @Name,
                    @RepairAddressId,
                    @RepairContactId,
                    @RepairOfficialAddressId,
                    @RepairOfficialContactId,
                    @DepartmentPrefix,
                    @CostCentreCode,
                    @RepairDefaultSecurityGroupId,
                    @RepairParentId,
                    @RepairNewOrgNode,
                    @QuoteThreshold
                );

                EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'OrganisationalUnits', N'RepairInsert', 1, N'Repaired an orphan DataObject by inserting the missing OrganisationalUnit row.';
            END
            ELSE
            BEGIN
                EXEC SCore.OrganisationalUnitsUpsert
                    @ParentOrganisationalUnitGuid = @ResolvedParentGuid,
                    @Name = @Name,
                    @AddressGuid = @AddressGuid,
                    @ContactGuid = @ContactGuid,
                    @OfficialAddressGuid = @OfficialAddressGuid,
                    @OfficialContactGuid = @OfficialContactGuid,
                    @DepartmentPrefix = @DepartmentPrefix,
                    @CostCentreCode = @CostCentreCode,
                    @DefaultSecurityGroupGuid = @DefaultSecurityGroupGuid,
                    @Guid = @ApplyOuGuid OUTPUT,
                    @QuoteThreshold = @QuoteThreshold;
            END;

            SET @cnt += 1;

            FETCH NEXT FROM cur_ou INTO @Guid;
        END;

        CLOSE cur_ou;
        DEALLOCATE cur_ou;

        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'OrganisationalUnits', N'Upsert', @cnt, N'Applied Guid/name-safe OU upserts.';

        UPDATE i
           SET i.OrganisationalUnitGuid = m.TargetOrganisationalUnitGuid
        FROM SMigration.Onboarding_Identities AS i
        INNER JOIN @OrganisationalUnitGuidRemap AS m
            ON m.SourceOrganisationalUnitGuid = i.OrganisationalUnitGuid
        WHERE i.RunGuid = @RunGuid;

        UPDATE jt
           SET jt.OrganisationalUnitGuid = m.TargetOrganisationalUnitGuid
        FROM SMigration.Onboarding_JobTypes AS jt
        INNER JOIN @OrganisationalUnitGuidRemap AS m
            ON m.SourceOrganisationalUnitGuid = jt.OrganisationalUnitGuid
        WHERE jt.RunGuid = @RunGuid;

        /* ========================================================================================
           5. Identities
           Match order:
           1) Guid
           2) EmailAddress, trimmed/case-insensitive
           ======================================================================================== */
        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.FullName = s.FullName,
               t.EmailAddress = s.EmailAddress,
               t.UserGuid = s.UserGuid,
               t.JobTitle = s.JobTitle,
               t.OriganisationalUnitId = ou.ID,
               t.IsActive = s.IsActive,
               t.ContactId = c.ID,
               t.BillableRate = s.BillableRate,
               t.Signature = s.Signature
        FROM SCore.Identities AS t
        INNER JOIN SMigration.Onboarding_Identities AS s
            ON s.IdentityGuid = t.Guid
        INNER JOIN SCore.OrganisationalUnits AS ou
            ON ou.Guid = s.OrganisationalUnitGuid
        INNER JOIN SCrm.Contacts AS c
            ON c.Guid = s.ContactGuid
        WHERE s.RunGuid = @RunGuid
          AND t.ID > 0
          AND s.IdentityGuid <> @ZeroGuid;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Identities', N'Update', @cnt, N'Updated identities matched by Guid.';

        ;WITH EmailMatches AS
        (
            SELECT
                s.IdentityGuid AS SourceIdentityGuid,
                t.Guid AS TargetIdentityGuid,
                ROW_NUMBER() OVER
                (
                    PARTITION BY s.IdentityGuid
                    ORDER BY
                        CASE WHEN t.RowStatus NOT IN (0, 254) THEN 0 ELSE 1 END,
                        t.ID
                ) AS MatchRank
            FROM SMigration.Onboarding_Identities AS s
            INNER JOIN SCore.Identities AS t
                ON t.ID > 0
               AND LOWER(LTRIM(RTRIM(t.EmailAddress))) = LOWER(LTRIM(RTRIM(s.EmailAddress)))
            WHERE s.RunGuid = @RunGuid
              AND s.IdentityGuid <> @ZeroGuid
              AND NULLIF(LTRIM(RTRIM(s.EmailAddress)), N'') IS NOT NULL
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM SCore.Identities AS x
                  WHERE x.Guid = s.IdentityGuid
                    AND x.ID > 0
              )
        )
        INSERT INTO @IdentityGuidRemap
        (
            SourceIdentityGuid,
            TargetIdentityGuid
        )
        SELECT
            em.SourceIdentityGuid,
            em.TargetIdentityGuid
        FROM EmailMatches AS em
        WHERE em.MatchRank = 1;

        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.FullName = s.FullName,
               t.EmailAddress = s.EmailAddress,
               t.UserGuid = s.UserGuid,
               t.JobTitle = s.JobTitle,
               t.OriganisationalUnitId = ou.ID,
               t.IsActive = s.IsActive,
               t.ContactId = c.ID,
               t.BillableRate = s.BillableRate,
               t.Signature = s.Signature
        FROM @IdentityGuidRemap AS m
        INNER JOIN SMigration.Onboarding_Identities AS s
            ON s.RunGuid = @RunGuid
           AND s.IdentityGuid = m.SourceIdentityGuid
        INNER JOIN SCore.Identities AS t
            ON t.Guid = m.TargetIdentityGuid
           AND t.ID > 0
        INNER JOIN SCore.OrganisationalUnits AS ou
            ON ou.Guid = s.OrganisationalUnitGuid
        INNER JOIN SCrm.Contacts AS c
            ON c.Guid = s.ContactGuid;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Identities', N'Update', @cnt, N'Updated identities matched by EmailAddress.';

        UPDATE ug
           SET ug.IdentityGuid = m.TargetIdentityGuid
        FROM SMigration.Onboarding_UserGroups AS ug
        INNER JOIN @IdentityGuidRemap AS m
            ON m.SourceIdentityGuid = ug.IdentityGuid
        WHERE ug.RunGuid = @RunGuid;

        DECLARE cur_ident CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.IdentityGuid
        FROM SMigration.Onboarding_Identities AS s
        WHERE s.RunGuid = @RunGuid
          AND s.IdentityGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.Identities AS t
              WHERE t.Guid = s.IdentityGuid
                AND t.ID > 0
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.Identities AS t
              WHERE t.ID > 0
                AND NULLIF(LTRIM(RTRIM(s.EmailAddress)), N'') IS NOT NULL
                AND LOWER(LTRIM(RTRIM(t.EmailAddress))) = LOWER(LTRIM(RTRIM(s.EmailAddress)))
          );

        OPEN cur_ident;
        FETCH NEXT FROM cur_ident INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            DECLARE
                @FullName NVARCHAR(250),
                @EmailAddress NVARCHAR(150),
                @UserGuid UNIQUEIDENTIFIER,
                @JobTitle NVARCHAR(50),
                @OUguid UNIQUEIDENTIFIER,
                @IsActive BIT,
                @ContactGuid2 UNIQUEIDENTIFIER,
                @BillableRate DECIMAL(19, 2),
                @Signature VARBINARY(MAX),
                @RowsInserted INT,
                @NewIdentityId INT;

            SELECT
                @FullName = s.FullName,
                @EmailAddress = s.EmailAddress,
                @UserGuid = s.UserGuid,
                @JobTitle = s.JobTitle,
                @OUguid = s.OrganisationalUnitGuid,
                @IsActive = s.IsActive,
                @ContactGuid2 = s.ContactGuid,
                @BillableRate = s.BillableRate,
                @Signature = s.Signature
            FROM SMigration.Onboarding_Identities AS s
            WHERE s.RunGuid = @RunGuid
              AND s.IdentityGuid = @Guid;

            EXEC SCore.UpsertDataObject
                @Guid = @Guid,
                @SchemeName = N'SCore',
                @ObjectName = N'Identities',
                @IncludeDefaultSecurity = 0,
                @IsInsert = @IsInsert OUTPUT;

            INSERT INTO SCore.Identities
            (
                RowStatus,
                Guid,
                FullName,
                EmailAddress,
                UserGuid,
                JobTitle,
                OriganisationalUnitId,
                IsActive,
                ContactId,
                BillableRate,
                Signature
            )
            SELECT
                1,
                @Guid,
                @FullName,
                @EmailAddress,
                @UserGuid,
                @JobTitle,
                ou.ID,
                @IsActive,
                c.ID,
                @BillableRate,
                @Signature
            FROM SCore.OrganisationalUnits AS ou
            INNER JOIN SCrm.Contacts AS c
                ON c.Guid = @ContactGuid2
            WHERE ou.Guid = @OUguid;

            SET @RowsInserted = @@ROWCOUNT;
            SET @cnt += @RowsInserted;

            IF @RowsInserted > 0
            BEGIN
                SELECT
                    @NewIdentityId = i.ID
                FROM SCore.Identities AS i
                WHERE i.Guid = @Guid;

                IF @NewIdentityId IS NOT NULL
                   AND NOT EXISTS
                   (
                       SELECT 1
                       FROM SCore.UserPreferences AS up
                       WHERE up.ID = @NewIdentityId
                   )
                BEGIN
                    INSERT INTO SCore.UserPreferences
                    (
                        ID,
                        Guid,
                        RowStatus,
                        SystemLanguageID,
                        WidgetLayout,
                        OutlookSettings
                    )
                    VALUES
                    (
                        @NewIdentityId,
                        @Guid,
                        1,
                        1,
                        N'{"ItemStates": []}',
                        N'{}'
                    );
                END;
            END;

            FETCH NEXT FROM cur_ident INTO @Guid;
        END;

        CLOSE cur_ident;
        DEALLOCATE cur_ident;

        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'Identities', N'Insert', @cnt, N'Inserted new identities only.';

        /* Ensure all active identities have required 1:1 UserPreferences rows */
        INSERT INTO SCore.UserPreferences
        (
            ID,
            Guid,
            RowStatus,
            SystemLanguageID,
            WidgetLayout,
            OutlookSettings
        )
        SELECT
            i.ID,
            i.Guid,
            1,
            1,
            N'{"ItemStates": []}',
            N'{}'
        FROM SCore.Identities AS i
        WHERE i.ID > 0
          AND i.RowStatus NOT IN (0,254)
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.UserPreferences AS up
              WHERE up.ID = i.ID
          );

        SET @cnt = @@ROWCOUNT;

        EXEC SMigration.OnboardingLog_Add
            @RunGuid,
            N'Import',
            N'UserPreferences',
            N'Insert',
            @cnt,
            N'Inserted missing UserPreferences rows for staged identities.';

        /* ========================================================================================
           6. UserGroups
           Natural key: IdentityID + GroupID + RowStatus.

           Rules:
           - Ignore sentinel GUID rows.
           - Resolve staged IdentityGuid and GroupGuid before comparing.
           - Do not update a Guid-matched row into a natural-key duplicate.
           - Do not insert if another row already owns IdentityID + GroupID + RowStatus.
           - Create SCore.DataObjects only for true insert candidates.
           ======================================================================================== */

        DECLARE @UserGroupInsertCandidates TABLE
        (
            UserGroupGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            RowStatus INT NOT NULL,
            IdentityID INT NOT NULL,
            GroupID INT NOT NULL
        );

        ;WITH SourceUserGroups AS
        (
            SELECT
                s.UserGroupGuid,
                s.RowStatus,
                i.ID AS IdentityID,
                g.ID AS GroupID,
                ROW_NUMBER() OVER
                (
                    PARTITION BY i.ID, g.ID, s.RowStatus
                    ORDER BY s.UserGroupGuid
                ) AS NaturalRank
            FROM SMigration.Onboarding_UserGroups AS s
            INNER JOIN SCore.Identities AS i
                ON i.Guid = s.IdentityGuid
               AND i.ID > 0
            INNER JOIN SCore.Groups AS g
                ON g.Guid = s.GroupGuid
               AND g.ID > 0
            WHERE s.RunGuid = @RunGuid
              AND s.UserGroupGuid <> @ZeroGuid
        )
        UPDATE t
           SET t.RowStatus = s.RowStatus,
               t.IdentityID = s.IdentityID,
               t.GroupID = s.GroupID
        FROM SCore.UserGroups AS t
        INNER JOIN SourceUserGroups AS s
            ON s.UserGroupGuid = t.Guid
        WHERE t.ID > 0
          AND s.NaturalRank = 1
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.UserGroups AS x
              WHERE x.ID <> t.ID
                AND x.IdentityID = s.IdentityID
                AND x.GroupID = s.GroupID
                AND x.RowStatus = s.RowStatus
          );

        SET @cnt = @@ROWCOUNT;

        EXEC SMigration.OnboardingLog_Add
            @RunGuid,
            N'Import',
            N'UserGroups',
            N'Update',
            @cnt,
            N'Updated user groups matched by Guid where no natural-key collision exists.';

        ;WITH SourceUserGroups AS
        (
            SELECT
                s.UserGroupGuid,
                s.RowStatus,
                i.ID AS IdentityID,
                g.ID AS GroupID,
                ROW_NUMBER() OVER
                (
                    PARTITION BY i.ID, g.ID, s.RowStatus
                    ORDER BY s.UserGroupGuid
                ) AS NaturalRank
            FROM SMigration.Onboarding_UserGroups AS s
            INNER JOIN SCore.Identities AS i
                ON i.Guid = s.IdentityGuid
               AND i.ID > 0
            INNER JOIN SCore.Groups AS g
                ON g.Guid = s.GroupGuid
               AND g.ID > 0
            WHERE s.RunGuid = @RunGuid
              AND s.UserGroupGuid <> @ZeroGuid
        )
        INSERT INTO @UserGroupInsertCandidates
        (
            UserGroupGuid,
            RowStatus,
            IdentityID,
            GroupID
        )
        SELECT
            s.UserGroupGuid,
            s.RowStatus,
            s.IdentityID,
            s.GroupID
        FROM SourceUserGroups AS s
        WHERE s.NaturalRank = 1
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.UserGroups AS t
              WHERE t.Guid = s.UserGroupGuid
                AND t.ID > 0
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.UserGroups AS t
              WHERE t.IdentityID = s.IdentityID
                AND t.GroupID = s.GroupID
                AND t.RowStatus = s.RowStatus
          );

        /*
           Guard against target identity-seed drift before inserting SCore.UserGroups.
           Some environments contain user-created rows whose ID is higher than the current
           identity seed. SQL Server would otherwise attempt to allocate an existing ID and
           fail with PK_UserGroups even though the staged natural key is not a duplicate.
        */
        DECLARE @MaxUserGroupIdentityValue INT;

        SELECT
            @MaxUserGroupIdentityValue = ISNULL(MAX(targetUserGroup.ID), 0)
        FROM SCore.UserGroups AS targetUserGroup WITH (HOLDLOCK);

        DBCC CHECKIDENT (N'SCore.UserGroups', RESEED, @MaxUserGroupIdentityValue) WITH NO_INFOMSGS;

        DECLARE cur_ug CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            c.UserGroupGuid
        FROM @UserGroupInsertCandidates AS c;

        OPEN cur_ug;
        FETCH NEXT FROM cur_ug INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC SCore.UpsertDataObject
                @Guid = @Guid,
                @SchemeName = N'SCore',
                @ObjectName = N'UserGroups',
                @IncludeDefaultSecurity = 0,
                @IsInsert = @IsInsert OUTPUT;

            FETCH NEXT FROM cur_ug INTO @Guid;
        END;

        CLOSE cur_ug;
        DEALLOCATE cur_ug;

        INSERT INTO SCore.UserGroups
        (
            Guid,
            RowStatus,
            IdentityID,
            GroupID
        )
        SELECT
            c.UserGroupGuid,
            c.RowStatus,
            c.IdentityID,
            c.GroupID
        FROM @UserGroupInsertCandidates AS c
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM SCore.UserGroups AS t
            WHERE t.Guid = c.UserGroupGuid
              AND t.ID > 0
        )
          AND NOT EXISTS
        (
            SELECT 1
            FROM SCore.UserGroups AS t
            WHERE t.IdentityID = c.IdentityID
              AND t.GroupID = c.GroupID
              AND t.RowStatus = c.RowStatus
        );

        SET @cnt = @@ROWCOUNT;

        EXEC SMigration.OnboardingLog_Add
            @RunGuid,
            N'Import',
            N'UserGroups',
            N'Insert',
            @cnt,
            N'Inserted distinct missing user groups only.';

/* ========================================================================================
   7. WorkflowStatuses
   Match order:
   1) Guid
   2) Name + resolved OrganisationalUnitID
   3) Insert true missing WorkflowStatus
   ======================================================================================== */
        UPDATE t
        SET
            t.RowStatus = s.RowStatus,
            t.OrganisationalUnitId = ISNULL(ou.ID, -1),
            t.Name = s.Name,
            t.Description = s.Description,
            t.ShowInEnquiries = s.ShowInEnquiries,
            t.ShowInQuotes = s.ShowInQuotes,
            t.ShowInJobs = s.ShowInJobs,
            t.Enabled = s.Enabled,
            t.IsPredefined = s.IsPredefined,
            t.SortOrder = s.SortOrder,
            t.Colour = s.Colour,
            t.Icon = s.Icon,
            t.SendNotification = s.SendNotification,
            t.IsCompleteStatus = s.IsCompleteStatus,
            t.IsCustomerWaitingStatus = s.IsCustomerWaitingStatus,
            t.RequiresUsersAction = s.RequiresUsersAction,
            t.IsActiveStatus = s.IsActiveStatus,
            t.AuthorisationNeeded = s.AuthorisationNeeded,
            t.IsAuthStatus = s.IsAuthStatus
        FROM SCore.WorkflowStatus AS t
        INNER JOIN SMigration.Onboarding_WorkflowStatuses AS s
            ON s.WorkflowStatusGuid = t.Guid
           AND t.ID > 0
        LEFT JOIN @OrganisationalUnitGuidRemap AS ouMap
            ON ouMap.SourceOrganisationalUnitGuid = s.OrganisationalUnitGuid
        LEFT JOIN SCore.OrganisationalUnits AS ou
            ON ou.Guid = COALESCE(ouMap.TargetOrganisationalUnitGuid, s.OrganisationalUnitGuid)
        WHERE s.RunGuid = @RunGuid
          AND s.WorkflowStatusGuid <> @ZeroGuid;

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'WorkflowStatuses', N'Update', @cnt, N'Updated workflow statuses matched by Guid.';

        ;WITH NameMatches AS
        (
            SELECT
                s.WorkflowStatusGuid AS SourceWorkflowStatusGuid,
                t.Guid AS TargetWorkflowStatusGuid,
                ROW_NUMBER() OVER
                (
                    PARTITION BY s.WorkflowStatusGuid
                    ORDER BY
                        CASE WHEN t.RowStatus NOT IN (0,254) THEN 0 ELSE 1 END,
                        t.ID
                ) AS MatchRank
            FROM SMigration.Onboarding_WorkflowStatuses AS s
            LEFT JOIN @OrganisationalUnitGuidRemap AS ouMap
                ON ouMap.SourceOrganisationalUnitGuid = s.OrganisationalUnitGuid
            LEFT JOIN SCore.OrganisationalUnits AS ou
                ON ou.Guid = COALESCE(ouMap.TargetOrganisationalUnitGuid, s.OrganisationalUnitGuid)
            INNER JOIN SCore.WorkflowStatus AS t
                ON LOWER(LTRIM(RTRIM(t.Name))) = LOWER(LTRIM(RTRIM(s.Name)))
               AND ISNULL(t.OrganisationalUnitId, -1) = ISNULL(ou.ID, -1)
               AND t.ID > 0
            WHERE s.RunGuid = @RunGuid
              AND s.WorkflowStatusGuid <> @ZeroGuid
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM SCore.WorkflowStatus AS x
                  WHERE x.Guid = s.WorkflowStatusGuid
                    AND x.ID > 0
              )
        )
        INSERT INTO @WorkflowStatusGuidRemap
        (
            SourceWorkflowStatusGuid,
            TargetWorkflowStatusGuid
        )
        SELECT
            nm.SourceWorkflowStatusGuid,
            nm.TargetWorkflowStatusGuid
        FROM NameMatches AS nm
        WHERE nm.MatchRank = 1
          AND NOT EXISTS
          (
              SELECT 1
              FROM @WorkflowStatusGuidRemap AS x
              WHERE x.SourceWorkflowStatusGuid = nm.SourceWorkflowStatusGuid
          );

        UPDATE t
        SET
            t.RowStatus = s.RowStatus,
            t.OrganisationalUnitId = ISNULL(ou.ID, -1),
            t.Name = s.Name,
            t.Description = s.Description,
            t.ShowInEnquiries = s.ShowInEnquiries,
            t.ShowInQuotes = s.ShowInQuotes,
            t.ShowInJobs = s.ShowInJobs,
            t.Enabled = s.Enabled,
            t.IsPredefined = s.IsPredefined,
            t.SortOrder = s.SortOrder,
            t.Colour = s.Colour,
            t.Icon = s.Icon,
            t.SendNotification = s.SendNotification,
            t.IsCompleteStatus = s.IsCompleteStatus,
            t.IsCustomerWaitingStatus = s.IsCustomerWaitingStatus,
            t.RequiresUsersAction = s.RequiresUsersAction,
            t.IsActiveStatus = s.IsActiveStatus,
            t.AuthorisationNeeded = s.AuthorisationNeeded,
            t.IsAuthStatus = s.IsAuthStatus
        FROM @WorkflowStatusGuidRemap AS m
        INNER JOIN SMigration.Onboarding_WorkflowStatuses AS s
            ON s.RunGuid = @RunGuid
           AND s.WorkflowStatusGuid = m.SourceWorkflowStatusGuid
        INNER JOIN SCore.WorkflowStatus AS t
            ON t.Guid = m.TargetWorkflowStatusGuid
           AND t.ID > 0
        LEFT JOIN @OrganisationalUnitGuidRemap AS ouMap
            ON ouMap.SourceOrganisationalUnitGuid = s.OrganisationalUnitGuid
        LEFT JOIN SCore.OrganisationalUnits AS ou
            ON ou.Guid = COALESCE(ouMap.TargetOrganisationalUnitGuid, s.OrganisationalUnitGuid);

        SET @cnt = @@ROWCOUNT;
        EXEC SMigration.OnboardingLog_Add @RunGuid, N'Import', N'WorkflowStatuses', N'Update', @cnt, N'Updated workflow statuses matched by Name + OU.';

        UPDATE wt
           SET wt.FromStatusGuid = m.TargetWorkflowStatusGuid
        FROM SMigration.Onboarding_WorkflowTransitions AS wt
        INNER JOIN @WorkflowStatusGuidRemap AS m
            ON m.SourceWorkflowStatusGuid = wt.FromStatusGuid
        WHERE wt.RunGuid = @RunGuid;

        UPDATE wt
           SET wt.ToStatusGuid = m.TargetWorkflowStatusGuid
        FROM SMigration.Onboarding_WorkflowTransitions AS wt
        INNER JOIN @WorkflowStatusGuidRemap AS m
            ON m.SourceWorkflowStatusGuid = wt.ToStatusGuid
        WHERE wt.RunGuid = @RunGuid;

        UPDATE wsng
           SET wsng.WorkflowStatusGuid = m.TargetWorkflowStatusGuid
        FROM SMigration.Onboarding_WorkflowStatusNotificationGroups AS wsng
        INNER JOIN @WorkflowStatusGuidRemap AS m
            ON m.SourceWorkflowStatusGuid = wsng.WorkflowStatusGuid
        WHERE wsng.RunGuid = @RunGuid;

        DECLARE cur_workflow_statuses CURSOR LOCAL FAST_FORWARD FOR
        SELECT s.WorkflowStatusGuid
        FROM SMigration.Onboarding_WorkflowStatuses AS s
        LEFT JOIN @OrganisationalUnitGuidRemap AS ouMap
            ON ouMap.SourceOrganisationalUnitGuid = s.OrganisationalUnitGuid
        LEFT JOIN SCore.OrganisationalUnits AS ou
            ON ou.Guid = COALESCE(ouMap.TargetOrganisationalUnitGuid, s.OrganisationalUnitGuid)
        WHERE s.RunGuid = @RunGuid
          AND s.WorkflowStatusGuid <> @ZeroGuid
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.WorkflowStatus AS t
              WHERE t.Guid = s.WorkflowStatusGuid
                AND t.ID > 0
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM SCore.WorkflowStatus AS t
              WHERE t.ID > 0
                AND LOWER(LTRIM(RTRIM(t.Name))) = LOWER(LTRIM(RTRIM(s.Name)))
                AND ISNULL(t.OrganisationalUnitId, -1) = ISNULL(ou.ID, -1)
          );

        OPEN cur_workflow_statuses;
        FETCH NEXT FROM cur_workflow_statuses INTO @Guid;

        SET @cnt = 0;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC SCore.UpsertDataObject
                @Guid = @Guid,
                @SchemeName = N'SCore',
                @ObjectName = N'WorkflowStatus',
                @IncludeDefaultSecurity = 0,
                @IsInsert = @IsInsert OUTPUT;

            INSERT INTO SCore.WorkflowStatus
            (
                RowStatus,
                Guid,
                OrganisationalUnitId,
                Name,
                Description,
                ShowInEnquiries,
                ShowInQuotes,
                ShowInJobs,
                Enabled,
                IsPredefined,
                SortOrder,
                Colour,
                Icon,
                SendNotification,
                IsCompleteStatus,
                IsCustomerWaitingStatus,
                RequiresUsersAction,
                IsActiveStatus,
                AuthorisationNeeded,
                IsAuthStatus
            )
            SELECT
                s.RowStatus,
                s.WorkflowStatusGuid,
                ISNULL(ou.ID, -1),
                s.Name,
                s.Description,
                s.ShowInEnquiries,
                s.ShowInQuotes,
                s.ShowInJobs,
                s.Enabled,
                s.IsPredefined,
                s.SortOrder,
                s.Colour,
                s.Icon,
                s.SendNotification,
                s.IsCompleteStatus,
                s.IsCustomerWaitingStatus,
                s.RequiresUsersAction,
                s.IsActiveStatus,
                s.AuthorisationNeeded,
                s.IsAuthStatus
            FROM SMigration.Onboarding_WorkflowStatuses AS s
            LEFT JOIN @OrganisationalUnitGuidRemap AS ouMap
                ON ouMap.SourceOrganisationalUnitGuid = s.OrganisationalUnitGuid
            LEFT JOIN SCore.OrganisationalUnits AS ou
                ON ou.Guid = COALESCE(ouMap.TargetOrganisationalUnitGuid, s.OrganisationalUnitGuid)
            WHERE s.RunGuid = @RunGuid
