                    CONVERT(NVARCHAR(36), s.PrimaryAddressGuid) AS PrimaryAddressGuid,
                    s.FirstName,
                    s.Initials,
                    s.Surname,
                    s.PostNominals,
                    ISNULL(CONVERT(NVARCHAR(36), s.TitleGuid), N'') AS TitleGuid,
