/* Deploy StoredProcedure SMigration.OnboardingRunEntitySelection_Default using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.OnboardingRunEntitySelection_Default.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SMigration.OnboardingRunEntitySelection_Default
    Source schema hash : C28307460194937CB70C73F23198200A5C8D13F0D8553FF07E1625509794CDB6
    Definition SHA-256 : D5C0BA504E851B761675B2BD123548C8C711734769D03E5027AFB1E44DD3AA16

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SMigration].[OnboardingRunEntitySelection_Default]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @RunGuid IS NULL
        THROW 62200, 'RunGuid is required for OnBoarding entity selection defaults.', 1;

    EXEC SMigration.OnboardingEntityScope_Seed;

    DECLARE
        @SelectionGuid UNIQUEIDENTIFIER,
        @EntityScopeGuid UNIQUEIDENTIFIER,
        @EntityCode NVARCHAR(100),
        @DefaultSelected BIT;

    DECLARE selection_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT
            NEWID() AS SelectionGuid,
            es.Guid AS EntityScopeGuid,
            es.Code AS EntityCode,
            es.DefaultSelected
        FROM SMigration.Onboarding_EntityScope AS es
        WHERE es.RowStatus NOT IN (0,254)
          AND es.IsSupportData = 0
          AND NOT EXISTS
          (
              SELECT 1
              FROM SMigration.Onboarding_RunEntitySelections AS existing
              WHERE existing.RunGuid = @RunGuid
                AND existing.EntityCode = es.Code
          )
        ORDER BY es.DisplayOrder;

    OPEN selection_cursor;
    FETCH NEXT FROM selection_cursor INTO @SelectionGuid, @EntityScopeGuid, @EntityCode, @DefaultSelected;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SMigration.MetadataDataObject_Ensure
            @Guid = @SelectionGuid,
            @SchemeName = N'SMigration',
            @ObjectName = N'Onboarding_RunEntitySelections';

        INSERT INTO SMigration.Onboarding_RunEntitySelections
        (
            Guid,
            RowStatus,
            RunGuid,
            EntityScopeGuid,
            EntityCode,
            IsSelected,
            SelectionSource,
            SelectedByUserId,
            SelectedOnUtc
        )
        VALUES
        (
            @SelectionGuid,
            1,
            @RunGuid,
            @EntityScopeGuid,
            @EntityCode,
            @DefaultSelected,
            N'Default',
            ISNULL(SCore.GetCurrentUserId(), -1),
            SYSUTCDATETIME()
        );

        FETCH NEXT FROM selection_cursor INTO @SelectionGuid, @EntityScopeGuid, @EntityCode, @DefaultSelected;
    END;

    CLOSE selection_cursor;
    DEALLOCATE selection_cursor;

    UPDATE sel
    SET
        RowStatus = CASE WHEN sel.RowStatus IN (0,254) THEN 1 ELSE sel.RowStatus END,
        EntityScopeGuid = es.Guid
    FROM SMigration.Onboarding_RunEntitySelections AS sel
    INNER JOIN SMigration.Onboarding_EntityScope AS es
        ON es.Code = sel.EntityCode
       AND es.RowStatus NOT IN (0,254)
       AND es.IsSupportData = 0
    WHERE sel.RunGuid = @RunGuid;
END;
GO

