/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SUserInterface.MainMenuItemsUpsert
    Source schema hash : 3356FFEC7A26DFA3A5CC32D4FE655FE0C54310E767D83F35B6177530F98C8BB6
    Definition SHA-256 : AE2855F0BB1730B052B9E28EEFB0101533E3D12A4975166E51A70DD3B24FE5A3

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SUserInterface].[MainMenuItemsUpsert]
  (
    @RowStatus         TINYINT,
    @LanguageLabelGuid UNIQUEIDENTIFIER,
	@IconGuid		   UNIQUEIDENTIFIER,
	@SortOrder		   INT,
	@NavigationUrl	   NVARCHAR(500),
    @Guid              UNIQUEIDENTIFIER OUT
  )
AS
  BEGIN
    DECLARE @LanguageLabelId INT,
			@IconId INT

    SELECT
            @LanguageLabelId = ID
    FROM
            SCore.LanguageLabels ll
    WHERE
            (Guid = @LanguageLabelGuid)

	-- Icons is no longer a migrated metadata table, so @IconGuid is often unresolved;
	-- fall back to the sentinel row on insert and leave the existing value alone on update.
	SELECT
			@IconId = ID
	FROM
			SUserInterface.Icons AS i
	WHERE
			(Guid = @IconGuid)

    DECLARE @IsInsert BIT
    EXEC SCore.UpsertDataObject
      @Guid       = @Guid,					-- uniqueidentifier
      @SchemeName = N'SUserInterface',				-- nvarchar(255)
      @ObjectName = N'MainMenuItems',				-- nvarchar(255)
      @IsInsert   = @IsInsert OUTPUT	-- bit

    IF (@IsInsert = 1)
      BEGIN
        INSERT SUserInterface.MainMenuItems
              (
                [Guid],
                [LanguageLabelId],
                [RowStatus],
                [IconId],
				[SortOrder],
				[NavigationUrl]
              )
        VALUES
                (
                  @Guid,
                  @LanguageLabelId,
                  1,
                  ISNULL(@IconId, -1),
				  @SortOrder,
				  @NavigationUrl
                )
      END
    ELSE
      BEGIN
        UPDATE  SUserInterface.MainMenuItems
        SET     LanguageLabelId = @LanguageLabelId,
                [RowStatus] = @RowStatus,
                [IconId] = ISNULL(@IconId, [IconId]),
				[SortOrder] = @SortOrder,
				[NavigationUrl] = @NavigationUrl
        WHERE
          ([Guid] = @Guid)
      END
  END
GO

